'use client';

import React, { useEffect, useState, use } from 'react';
import { ContentManagerApi, FullContentDisplayDto } from '@/features/content/api/ContentManagerApi';
import { Calendar, AlertCircle, User, ChevronRight } from 'lucide-react';
import Link from 'next/link';
import styles from './BlogDetail.module.scss';

interface PageProps {
  params: Promise<{ slug: string }>;
}

export default function BlogDetailContent({ params }: PageProps) {
  // باز کردن Promise پارامترها با هوک use (مخصوص Next.js 15+)
  const resolvedParams = use(params);
  const slug = resolvedParams.slug;

  const [article, setArticle] = useState<FullContentDisplayDto | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // دریافت اطلاعات مقاله از API بر اساس Slug
  useEffect(() => {
    let active = true;

    const fetchArticle = async () => {
      try {
        setLoading(true);
        setError(null);
        const decodedSlug = decodeURIComponent(slug);
        const response = await ContentManagerApi.getContentForDisplay(decodedSlug);
        if (!active) return;

        if (response.data.isSuccess && response.data.data) {
          setArticle(response.data.data);
        } else {
          setError(response.data.message || 'مقاله مورد نظر پیدا نشد.');
        }
      } catch (err: any) {
        if (active) {
          setError(err.response?.data?.message || 'ارتباط با سرور برقرار نشد.');
        }
      } finally {
        if (active) setLoading(false);
      }
    };

    if (slug) void fetchArticle();

    return () => {
      active = false;
    };
  }, [slug]);

  // وضعیت لودینگ (Skeleton Loading)
  if (loading) {
    return (
      <div className={styles.container}>
        <div className={styles.skeletonTitle}></div>
        <div className={styles.skeletonMeta}></div>
        <div className={styles.skeletonImage}></div>
        <div className={styles.skeletonText}></div>
        <div className={styles.skeletonText}></div>
        <div className={styles.skeletonText} style={{ width: '80%' }}></div>
      </div>
    );
  }

  // وضعیت خطا یا پیدا نشدن مقاله
  if (error || !article) {
    return (
      <div className={styles.container}>
        <div className={styles.error}>
          <AlertCircle size={48} />
          <h2>{error || 'محتوایی یافت نشد'}</h2>
          <Link href="/blog" className={styles.backToBlogBtn}>
            بازگشت به مجله کارنیکس
          </Link>
        </div>
      </div>
    );
  }

  return (
    <article className={styles.container}>
      {/* دکمه بازگشت */}
      <div className={styles.breadcrumb}>
        <Link href="/blog" className={styles.backLink}>
          <ChevronRight size={20} />
          بازگشت به مجله کارنیکس
        </Link>
      </div>

      <header className={styles.header}>
        <h1 className={styles.title}>{article.title}</h1>
        <div className={styles.meta}>
          {article.publishDate && (
            <span className={styles.metaItem}>
              <Calendar size={18} />
              {new Date(article.publishDate).toLocaleDateString('fa-IR')}
            </span>
          )}
          <span className={styles.metaItem}>
            <User size={18} />
            تیم تحریریه کارنیکس
          </span>
        </div>
      </header>

      {/* بدنه اصلی مقاله */}
      <div 
        className={styles.bodyContent}
        dangerouslySetInnerHTML={{ __html: article.body }} 
      />
    </article>
  );
}

import { Suspense } from 'react';
import BlogDetailContent from './BlogDetailContent';

interface PageProps {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  try {
    const { ContentManagerApi } = await import('@/features/content/api/ContentManagerApi');
    const response = await ContentManagerApi.getAllContents();

    if (response.data?.isSuccess && Array.isArray(response.data.data)) {
      return response.data.data.map((article: any) => ({
        slug: String(article.slug || article.id),
      }));
    }
  } catch (error) {
    if (process.env.STRICT_SSG_DATA === 'true') {
      throw new Error('Blog data is required for strict static generation', { cause: error });
    }
    console.warn('Could not fetch blog posts for static generation; paths will be generated on demand.', error);
  }
  return [];
}

export const dynamicParams = true;

export default function BlogDetailPage({ params }: PageProps) {
  return (
    <Suspense fallback={<div>در حال بارگذاری مقاله...</div>}>
      <BlogDetailContent params={params} />
    </Suspense>
  );
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import { getMediaUrl } from '@/utils/media/getMediaUrl'
import Link from 'next/link'
import { ShieldCheck, Tag, Search, X } from 'lucide-react'
import { useAppDispatch, useAppSelector } from '@/store/hooks'
import { getAllBrands } from '@/store/feature/brand/BrandThunks'
import { selectBrands } from '@/store/feature/brand/BrandSelectors'
import styles from './BrandsPage.module.scss'
import type { RootState } from '@/store' 
import OptimizedImage from '@/components/common/OptimizedImage/OptimizedImage'

// تابع استخراج‌گر ایمن
const extractSafeArray = (data: any): any[] => {
  if (!data) return [];
  if (Array.isArray(data)) return data; 
  if (Array.isArray(data.items)) return data.items; 
  if (Array.isArray(data.data)) return data.data; 
  if (Array.isArray(data.mainResults)) return data.mainResults; 
  if (data.data && Array.isArray(data.data.items)) return data.data.items; 
  if (data.mainResults && Array.isArray(data.mainResults.items)) return data.mainResults.items;
  return [];
};

// تابع هوشمند برای اتصال آدرس سرور بک‌اند به آدرس عکس
const getImageUrl = (url: string | null | undefined) => getMediaUrl(url) ?? '';

const BrandsPage = () => {
  const dispatch = useAppDispatch()
  
  const rawBrands = useAppSelector(selectBrands)
  const loading = useAppSelector(
    (state: RootState) => state.brand?.loading || false,
  )
  const listStatus = useAppSelector(
    (state: RootState) => state.brand?.listStatus ?? 'idle',
  )

  const [searchTerm, setSearchTerm] = useState('')

  const safeBrandsArray = useMemo(() => extractSafeArray(rawBrands), [rawBrands]);

  useEffect(() => {
    if (listStatus === 'idle') {
      void dispatch(getAllBrands())
    }
  }, [dispatch, listStatus])

  const activeBrands = useMemo(() => {
    return safeBrandsArray
      .filter((b: any) => 
        b.isActive !== false && 
        (searchTerm.trim() === '' || (b.name && b.name.toLowerCase().includes(searchTerm.toLowerCase().trim())))
      )
      .sort((a: any, b: any) => (a.displayOrder || 0) - (b.displayOrder || 0));
  }, [safeBrandsArray, searchTerm])

  const clearSearch = () => {
    setSearchTerm('');
  };

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.pageHeader}>
        <div className={styles.headerTitleSection}>
          <div className={styles.iconWrapper}>
            <Tag size={24} className={styles.headerIcon} />
          </div>
          <h1 className={styles.pageTitle}>برندهای معتبر</h1>
        </div>

        <div className={styles.searchContainer}>
          <Search size={20} className={styles.searchIcon} />
          <input 
            type="text" 
            placeholder="جستجوی برند..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className={styles.searchInput}
          />
          {searchTerm && (
            <button onClick={clearSearch} className={styles.clearSearchBtn} aria-label="پاک کردن جستجو">
              <X size={16} />
            </button>
          )}
        </div>
      </div>

      {loading ? (
        <div className={styles.gridContainer}>
          {Array.from({ length: 8 }).map((_, index) => (
            <div key={`skeleton-${index}`} className={styles.skeletonCard}>
              <div className={styles.skeletonIcon}></div>
              <div className={styles.skeletonInfo}>
                <div className={styles.skeletonLineTitle}></div>
                <div className={styles.skeletonLineSub}></div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className={styles.gridContainer}>
          {activeBrands.map((brand: any) => (
            <Link
              key={brand.brandId}
              className={styles.brandCard}
              href={`/products?brandId=${encodeURIComponent(String(brand.brandId))}`}
              aria-label={`مشاهده محصولات برند ${brand.name}`}
            >
              <div className={styles.iconBox}>
                {brand.logoUrl ? (
                  <OptimizedImage src={getImageUrl(brand.logoUrl)} alt={brand.name} className={styles.logoImage} width={64} height={64} sizes="64px" />
                ) : (
                  <ShieldCheck size={28} strokeWidth={1.5} className={styles.defaultIcon} />
                )}
              </div>

              <div className={styles.brandInfo}>
                <span className={styles.brandName}>{brand.name}</span>
                {brand.countryOfOrigin ? (
                  <span className={styles.brandCountry}>{brand.countryOfOrigin}</span>
                ) : (
                  <span className={styles.brandCountry}>برند تایید شده</span>
                )}
              </div>
            </Link>
          ))}
          
          {activeBrands.length === 0 && !loading && (
            <div className={styles.emptyState}>
              <ShieldCheck size={48} strokeWidth={1} className={styles.emptyIcon} />
              <span>{searchTerm ? 'برندی با این نام یافت نشد.' : 'برندی ثبت نشده است.'}</span>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default BrandsPage

import { Suspense } from 'react'
import CategoryProductsContent from './CategoryProductsContent'

interface PageProps {
  params: Promise<{ category: string }>
}

// این تابع لیست مسیرهای داینامیک را در زمان بیلد تولید می‌کند
export async function generateStaticParams() {
  try {
    // گرفتن لیست دسته‌بندی‌ها از API (در صورت دسترس بودن در زمان بیلد)
    const { CategoryApi } = await import('@/features/category/api/routes')
    const res = await CategoryApi.getAll()

    if (res.data?.isSuccess && Array.isArray(res.data.data)) {
      return res.data.data.map((cat: any) => ({
        category: cat.slug || String(cat.categoryId),
      }))
    }
  } catch (error) {
    if (process.env.STRICT_SSG_DATA === 'true') {
      throw new Error('Category data is required for strict static generation', { cause: error })
    }
    console.warn('Could not fetch categories for static generation; paths will be generated on demand.', error)
  }
  return []
}

export const dynamicParams = true

export default function CategoryProductsPage({ params }: PageProps) {
  return (
    <Suspense fallback={<div>در حال بارگذاری...</div>}>
      <CategoryProductsContent params={params} />
    </Suspense>
  )
}

'use client'

import React, { useEffect, useState, useCallback } from 'react'
import { useAppDispatch, useAppSelector } from '@/store/hooks'
import {
  fetchAddresses,
  deleteAddress,
  createAddress,
  updateAddress,
  setDefaultAddress
} from '@/store/feature/address/AddressThunks'
import {
  selectAddresses,
  selectAddressActionLoading,
  selectAddressError,
  selectAddressLoading,
  selectSelectedAddress
} from '@/store/feature/address/AddressSelectors'
import { setSelectedAddress } from '@/store/feature/address/AddressSlice'
import { useModalManager } from '@/hooks/useModalManager'
import AddressModal from '@/components/address/AddressModal'
import styles from './AddressesPage.module.scss'
import {
  IconMapPin,
  IconPlus,
  IconTrash,
  IconCheck,
  IconRefresh,
  IconAlertCircle,
  IconStar,
  IconLoader2,
  IconPhone,
  IconUser,
  IconMail
} from '@tabler/icons-react'
import { ChevronRight } from 'lucide-react'
import { useRouter } from 'next/navigation'

// Types
interface Address {
  userAddressId: number
  addressTitle: string
  recipientName: string
  phoneNumber: string
  landlineNumber?: string
  fullAddress: string
  city: string
  province: string
  postalCode: string
  isDefault: boolean
  isActive: boolean
  userId: number
  latitude?: number | null
  longitude?: number | null
}

type ModalMode = 'create' | 'edit' | 'delete' | null

// Skeletons & States
const SkeletonCard = () => (
  <div className={styles.skeletonCard}>
    <div className={styles.skeletonLine} style={{ width: '30%', height: '22px' }} />
    <div className={styles.skeletonLine} style={{ width: '80%' }} />
    <div className={styles.skeletonLine} style={{ width: '60%' }} />
  </div>
)

const ErrorState: React.FC<{ message: string; onRetry: () => void }> = ({ message, onRetry }) => (
  <div className={styles.errorState}>
    <IconAlertCircle size={48} stroke={1.5} />
    <h3>خطا در بارگذاری</h3>
    <p>{message || 'متأسفانه در دریافت اطلاعات آدرس‌ها مشکلی پیش آمده است.'}</p>
    <button className={styles.retryButton} onClick={onRetry}><IconRefresh size={20} /> تلاش مجدد</button>
  </div>
)

const EmptyState: React.FC<{ onAddAddress: () => void }> = ({ onAddAddress }) => (
  <div className={styles.emptyState}>
    <div className={styles.emptyIconWrapper}>
      <IconMapPin size={64} stroke={1} className={styles.emptyIcon} />
    </div>
    <h3>آدرسی ثبت نشده</h3>
    <p>شما هنوز هیچ آدرسی ثبت نکرده‌اید. با افزودن آدرس، فرآیند خرید را سریع‌تر کنید.</p>
    <button className={styles.addFirstAddress} onClick={onAddAddress}>
      <IconPlus size={20} /> ثبت اولین آدرس
    </button>
  </div>
)

export default function AddressesPage() {
  const dispatch = useAppDispatch()
  const router = useRouter()

  const rawAddresses = useAppSelector(selectAddresses)
  const addresses: Address[] = Array.isArray(rawAddresses) ? rawAddresses : []
  const selectedAddress = useAppSelector(selectSelectedAddress)
  const loading = useAppSelector(selectAddressLoading)
  const actionLoading = useAppSelector(selectAddressActionLoading)
  const error = useAppSelector(selectAddressError)

  const [retryCount, setRetryCount] = useState(0)
  const [modalMode, setModalMode] = useState<ModalMode>(null)
  const [addressToDelete, setAddressToDelete] = useState<Address | null>(null)
  const [isSettingDefault, setIsSettingDefault] = useState<number | null>(null)

  useModalManager(modalMode !== null)

  useEffect(() => {
    dispatch(fetchAddresses(retryCount > 0 ? { force: true } : undefined))
  }, [dispatch, retryCount])

  const handleRetry = useCallback(() => setRetryCount(prev => prev + 1), [])
  const handleOpenCreateModal = useCallback(() => {
    dispatch(setSelectedAddress(null))
    setModalMode('create')
  }, [dispatch])
  const handleOpenEditModal = useCallback((address: Address) => {
    dispatch(setSelectedAddress(address as any))
    setModalMode('edit')
  }, [dispatch])
  const handleOpenDeleteModal = useCallback((address: Address) => {
    setAddressToDelete(address)
    setModalMode('delete')
  }, [])
  const handleCloseModal = useCallback(() => {
    setModalMode(null)
    setAddressToDelete(null)
    dispatch(setSelectedAddress(null))
  }, [dispatch])

  const handleSetDefault = useCallback(async (addressId: number, e: React.MouseEvent) => {
    e.stopPropagation()
    setIsSettingDefault(addressId)
    try {
      await dispatch(setDefaultAddress(addressId)).unwrap()
    } catch (err) {
      console.error('Error setting default address:', err)
    } finally {
      setIsSettingDefault(null)
    }
  }, [dispatch])

  if (loading && addresses.length === 0) {
    return (
      <div className={styles.container}>
        <div className={styles.header}>
           <h2 className={styles.title}>آدرس های من</h2>
           <button className={styles.addButton} disabled><IconPlus size={16} /> آدرس جدید</button>
        </div>
        <div className={styles.addressList}>{[1, 2].map(i => <SkeletonCard key={i} />)}</div>
      </div>
    )
  }

  if (error && addresses.length === 0) {
    return (
      <div className={styles.container}>
        <div className={styles.header}>
           <h2 className={styles.title}>آدرس های من</h2>
        </div>
        <ErrorState message={error} onRetry={handleRetry} />
      </div>
    )
  }

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <div className={styles.mobileHeader}>
          <div className={styles.mobileTitleGroup}>
            {/* اصلاح روتیگ برای حل مشکل عدم باز شدن مجدد تب در سایدبار */}
            <button className={styles.backBtn} onClick={() => router.push('/profile/info')}>
              <ChevronRight size={20} />
            </button>
            <h2 className={styles.title}>آدرس های من</h2>
          </div>
          <button className={styles.mobileAddBtn} onClick={handleOpenCreateModal}>
            + افزودن آدرس جدید
          </button>
        </div>

        <div className={styles.desktopHeader}>
          <h2 className={styles.title}>آدرس های من</h2>
          <button className={styles.desktopAddBtn} onClick={handleOpenCreateModal}>
            + آدرس جدید
          </button>
        </div>
      </div>

      {error && addresses.length > 0 && (
        <div className={styles.errorBanner}>
          <IconAlertCircle size={18} /><span>{error}</span>
        </div>
      )}

      {loading && addresses.length > 0 && <div className={styles.loadingBar}><div className={styles.loadingProgress} /></div>}

      {addresses.length === 0 && !loading && !error ? (
        <EmptyState onAddAddress={handleOpenCreateModal} />
      ) : (
        <div className={styles.addressList}>
          {addresses.map(address => (
            <div key={address.userAddressId} className={`${styles.addressCard} ${address.isDefault ? styles.defaultCard : ''}`}>

              <div className={styles.cardContentRight}>
                <div className={styles.cardHeader}>
                  <h4 className={styles.addressTitle}>{address.addressTitle || 'آدرس من'}</h4>
                  <div className={styles.cardActionsHeader}>
                    {address.isDefault && <span className={styles.defaultBadge}><IconCheck size={14} /> پیش‌فرض</span>}
                    {!address.isDefault && (
                      <button className={styles.iconBtn} onClick={(e) => handleSetDefault(address.userAddressId, e)} title="تنظیم به عنوان پیش‌فرض">
                        {isSettingDefault === address.userAddressId ? <IconLoader2 size={16} className={styles.spinning} /> : <IconStar size={18} />}
                      </button>
                    )}
                    <button className={styles.iconBtnDanger} onClick={() => handleOpenDeleteModal(address)} title="حذف آدرس">
                      <IconTrash size={18} />
                    </button>
                  </div>
                </div>

                <p className={styles.fullAddressText}>{address.fullAddress}</p>

                <div className={styles.detailsGrid}>
                  <div className={styles.detailItem}>
                    <IconMapPin size={18} />
                    <span>{address.city}</span>
                  </div>
                  <div className={styles.detailItem}>
                    <IconPhone size={18} />
                    <span dir="ltr">{address.phoneNumber}</span>
                  </div>
                  <div className={styles.detailItem}>
                    <IconUser size={18} />
                    <span>{address.recipientName}</span>
                  </div>
                  <div className={styles.detailItem}>
                    <IconMail size={18} />
                    <span dir="ltr">{address.postalCode}</span>
                  </div>
                </div>
              </div>

              <div className={styles.cardContentLeft}>
                <div className={styles.mapThumbnail}>
                  {address.latitude && address.longitude ? (
                    <div className={styles.mapCropWrapper}>
                      <iframe
                        frameBorder="0"
                        scrolling="no"
                        marginHeight={0}
                        marginWidth={0}
                        src={`https://www.openstreetmap.org/export/embed.html?bbox=${address.longitude - 0.012},${address.latitude - 0.012},${address.longitude + 0.012},${address.latitude + 0.012}&layer=mapnik&marker=${address.latitude},${address.longitude}`}
                        title={`نقشه آدرس ${address.addressTitle}`}
                      />
                    </div>
                  ) : (
                    <div className={styles.mapPlaceholderBox}>
                      <IconMapPin size={24} className={styles.mapPinIcon} />
                      <span>موقعیت ثبت نشده</span>
                    </div>
                  )}
                </div>
                <button className={styles.editOutlineBtn} onClick={() => handleOpenEditModal(address)} disabled={!!actionLoading}>
                  ویرایش آدرس
                </button>
              </div>

            </div>
          ))}
        </div>
      )}

      {modalMode && (
        <AddressModal
          isOpen={modalMode !== null}
          onClose={handleCloseModal}
          initialData={modalMode === 'edit' ? selectedAddress : modalMode === 'delete' ? addressToDelete : undefined}
          mode={modalMode}
          userId={0}
        />
      )}
    </div>
  )
}

