                         <Car size={48} strokeWidth={1} />
                      </div>
                      <span className={styles.emptyStateText}>مدلی برای این برند یافت نشد.</span>
                    </div>
                  )}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  )
}

