// components/common/MapPicker/LeafletMapWrapper.tsx
'use client'

import React, { useEffect, useRef } from 'react'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'

// ===============================
// Types
// ===============================
interface MapLocation {
  lat: number
  lng: number
}

interface LeafletMapWrapperProps {
  center: MapLocation
  marker: MapLocation | null
  onMapClick: (lat: number, lng: number) => void
}

// ===============================
// Fix Leaflet Default Icons
// ===============================
const fixLeafletIcons = () => {
  // @ts-ignore
  delete L.Icon.Default.prototype._getIconUrl

  L.Icon.Default.mergeOptions({
    iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
    iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
    shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
  })
}

// ===============================
// Custom Marker Icon (SVG-based)
// ===============================
const createCustomIcon = () => {
  return L.divIcon({
    className: 'custom-map-marker',
    html: `
      <svg width="36" height="48" viewBox="0 0 36 48" fill="none" xmlns="http://www.w3.org/2000/svg">
        <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000" flood-opacity="0.25"/>
        </filter>
        <path d="M18 0C8.06 0 0 8.06 0 18C0 31.5 18 48 18 48C18 48 36 31.5 36 18C36 8.06 27.94 0 18 0Z" fill="#1a73e8" filter="url(#shadow)"/>
        <circle cx="18" cy="18" r="8" fill="white"/>
        <circle cx="18" cy="18" r="4" fill="#1a73e8"/>
      </svg>
    `,
    iconSize: [36, 48],
    iconAnchor: [18, 48],
    popupAnchor: [0, -48],
    tooltipAnchor: [0, -40],
  })
}

// ===============================
// LeafletMapWrapper Component
// ===============================
const LeafletMapWrapper: React.FC<LeafletMapWrapperProps> = ({
  center,
  marker,
  onMapClick,
}) => {
  // ===============================
  // Refs
  // ===============================
  const mapRef = useRef<L.Map | null>(null)
  const markerRef = useRef<L.Marker | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const clickHandlerRef = useRef(onMapClick)
  const isInitializedRef = useRef(false)

  // Keep click handler updated without re-creating map
  useEffect(() => {
    clickHandlerRef.current = onMapClick
  }, [onMapClick])

  // ===============================
  // Initialize Map (ONLY ONCE)
  // ===============================
  useEffect(() => {
    if (!containerRef.current || isInitializedRef.current) return

    fixLeafletIcons()

    const map = L.map(containerRef.current, {
      center: [center.lat, center.lng],
      zoom: 15,
      zoomControl: true,
      attributionControl: false,
      scrollWheelZoom: true,
      doubleClickZoom: true,
      dragging: true,
      zoomAnimation: true,
    })

    // Add OSM Tile Layer
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      minZoom: 4,
      crossOrigin: true,
    }).addTo(map)

    // Click handler - uses ref to avoid re-binding
    map.on('click', (e: L.LeafletMouseEvent) => {
      clickHandlerRef.current(e.latlng.lat, e.latlng.lng)
    })

    // Handle resize
    const resizeObserver = new ResizeObserver(() => {
      map.invalidateSize()
    })

    if (containerRef.current) {
      resizeObserver.observe(containerRef.current)
    }

    mapRef.current = map
    isInitializedRef.current = true

    return () => {
      resizeObserver.disconnect()
      map.remove()
      mapRef.current = null
      isInitializedRef.current = false
    }
  }, []) // Empty deps - initialize only once

  // ===============================
  // Update Center (when center prop changes)
  // ===============================
  useEffect(() => {
    if (!mapRef.current || !isInitializedRef.current) return

    const currentCenter = mapRef.current.getCenter()
    const newCenter = L.latLng(center.lat, center.lng)

    // Only update if center actually changed
    if (!currentCenter.equals(newCenter)) {
      mapRef.current.setView(newCenter, mapRef.current.getZoom(), {
        animate: true,
        duration: 0.3,
      })
    }
  }, [center.lat, center.lng])

  // ===============================
  // Update Marker (when marker prop changes)
  // ===============================
  useEffect(() => {
    if (!mapRef.current || !isInitializedRef.current) return

    // Remove old marker
    if (markerRef.current) {
      markerRef.current.remove()
      markerRef.current = null
    }

    // Add new marker
    if (marker) {
      const icon = createCustomIcon()

      markerRef.current = L.marker([marker.lat, marker.lng], {
        icon,
        draggable: true,
        autoPan: true,
        autoPanPadding: [50, 50],
        riseOnHover: true,
      })
        .addTo(mapRef.current)
        .bindPopup('📍 موقعیت انتخاب شده', {
          closeButton: true,
          autoClose: false,
          closeOnClick: false,
          className: 'custom-popup',
        })
        .openPopup()

      // Handle drag end
      markerRef.current.on('dragend', () => {
        const position = markerRef.current?.getLatLng()
        if (position) {
          clickHandlerRef.current(position.lat, position.lng)
        }
      })

      // Animate to marker
      mapRef.current.setView([marker.lat, marker.lng], mapRef.current.getZoom(), {
        animate: true,
        duration: 0.3,
      })
    }
  }, [marker?.lat, marker?.lng])

  // ===============================
  // Render
  // ===============================
  return (
    <div
      ref={containerRef}
      style={{
        width: '100%',
        height: '100%',
        cursor: 'crosshair',
        zIndex: 1,
      }}
    />
  )
}

// Memoize to prevent unnecessary re-renders
export default React.memo(LeafletMapWrapper, (prev, next) => {
  return (
    prev.center.lat === next.center.lat &&
    prev.center.lng === next.center.lng &&
    prev.marker?.lat === next.marker?.lat &&
    prev.marker?.lng === next.marker?.lng &&
    prev.onMapClick === next.onMapClick
  )
})

// components/common/MapPicker/MapPicker.tsx
'use client'

import React, { useState, useEffect, useCallback, useRef, memo } from 'react'
import dynamic from 'next/dynamic'
import { MapPin, Navigation, Search, AlertTriangle, Loader2, X } from 'lucide-react'
import styles from './MapPicker.module.scss'

// ===============================
// Loading Fallback
// ===============================
const MapLoadingFallback = () => (
  <div className={styles.loadingState}>
    <Loader2 size={32} className={styles.spinning} />
    <p>در حال بارگذاری نقشه...</p>
  </div>
)

// ===============================
// Dynamic Imports
// ===============================
const LeafletMapWrapper = dynamic(
  () => import('./LeafletMapWrapper'),
  { ssr: false, loading: MapLoadingFallback }
)

const NeshanMapWrapper = dynamic(
  () => import('./NeshanMapWrapper'),
  { ssr: false, loading: MapLoadingFallback }
)

// ===============================
// Types
// ===============================
export interface MapLocation {
  lat: number
  lng: number
}

export interface AddressSuggestion {
  address: string
  location: MapLocation
}

interface MapPickerProps {
  initialLocation?: MapLocation | null
  onLocationSelect: (lat: number, lng: number, address?: string) => void
  height?: string
  showSearch?: boolean
  showCurrentLocation?: boolean
  placeholder?: string
  disabled?: boolean
}

// ===============================
// Constants
// ===============================
const DEFAULT_CENTER: MapLocation = { lat: 35.6892, lng: 51.3890 }
const SEARCH_DEBOUNCE_MS = 600
const OSM_TILE_URL = 'https://tile.openstreetmap.org/0/0/0.png'
const NOMINATIM_SEARCH_URL = 'https://nominatim.openstreetmap.org/search'
const NOMINATIM_REVERSE_URL = 'https://nominatim.openstreetmap.org/reverse'

// ===============================
// Helper Functions
// ===============================
const fetchWithTimeout = async (
  url: string,
  timeout = 5000,
  init: RequestInit = {},
) => {
  const controller = new AbortController()
  const abortFromParent = () => controller.abort()
  init.signal?.addEventListener('abort', abortFromParent, { once: true })
  const timeoutId = window.setTimeout(() => controller.abort(), timeout)

  try {
    return await fetch(url, { ...init, signal: controller.signal })
  } finally {
    window.clearTimeout(timeoutId)
    init.signal?.removeEventListener('abort', abortFromParent)
  }
}

// ===============================
// MapPicker Component (Memoized)
// ===============================
const MapPicker: React.FC<MapPickerProps> = memo(({
  initialLocation,
  onLocationSelect,
  height = '400px',
  showSearch = true,
  showCurrentLocation = true,
  placeholder = 'جستجوی آدرس یا مکان...',
  disabled = false,
}) => {
  // ===============================
  // Refs
  // ===============================
  const searchInputRef = useRef<HTMLInputElement>(null)
  const isMountedRef = useRef(true)
  const onLocationSelectRef = useRef(onLocationSelect)
  const abortControllerRef = useRef<AbortController | null>(null)
  const reverseAbortControllerRef = useRef<AbortController | null>(null)

  // Keep callback ref updated without triggering re-renders
  useEffect(() => {
    onLocationSelectRef.current = onLocationSelect
  }, [onLocationSelect])

  // ===============================
  // State
  // ===============================
  const [selectedLocation, setSelectedLocation] = useState<MapLocation | null>(
    initialLocation || null
  )
  const [currentLocation, setCurrentLocation] = useState<MapLocation | null>(null)
  const [mapProvider, setMapProvider] = useState<'leaflet' | 'neshan' | null>(null)
  const [locationError, setLocationError] = useState<string | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<AddressSuggestion[]>([])
  const [isSearching, setIsSearching] = useState(false)
  const [isLocating, setIsLocating] = useState(false)
  const [mapError, setMapError] = useState<string | null>(null)
  const [showSearchResults, setShowSearchResults] = useState(false)

  // ===============================
  // Cleanup on unmount
  // ===============================
  useEffect(() => {
    // React StrictMode در development effect را setup/cleanup/setup می‌کند.
    isMountedRef.current = true

    return () => {
      isMountedRef.current = false
      abortControllerRef.current?.abort()
      reverseAbortControllerRef.current?.abort()
    }
  }, [])

  // ===============================
  // Sync initialLocation prop
  // ===============================
  useEffect(() => {
    if (initialLocation) {
      setSelectedLocation(initialLocation)
    }
  }, [initialLocation?.lat, initialLocation?.lng])

  // ===============================
  // Detect Map Provider (OSM or Neshan)
  // ===============================
  useEffect(() => {
    let cancelled = false

    const detectMapProvider = async () => {
      try {
        const response = await fetchWithTimeout(OSM_TILE_URL, 4000)
        if (!cancelled && response.ok) {
          setMapProvider('leaflet')
          return
        }
        throw new Error('OSM not available')
      } catch {
        if (!cancelled) {
          const apiKey = process.env.NEXT_PUBLIC_NESHAN_API_KEY
          if (apiKey && apiKey !== 'YOUR_API_KEY') {
            setMapProvider('neshan')
          } else {
            setMapError('نقشه در دسترس نیست. لطفاً API Key نشان را تنظیم کنید.')
          }
        }
      }
    }

    detectMapProvider()

    return () => {
      cancelled = true
    }
  }, [])

  // ===============================
  // Get Current Location
  // ===============================
  const getCurrentLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setLocationError('مرورگر شما از موقعیت‌یابی پشتیبانی نمی‌کند')
      return
    }

    setIsLocating(true)
    setLocationError(null)

    const options: PositionOptions = {
      enableHighAccuracy: true,
      timeout: 15000,
      maximumAge: 0,
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        if (!isMountedRef.current) return
        const location: MapLocation = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        }
        setCurrentLocation(location)
        if (!selectedLocation) {
          setSelectedLocation(location)
          onLocationSelectRef.current(location.lat, location.lng)
          reverseGeocode(location.lat, location.lng)
        }
        setIsLocating(false)
      },
      (error) => {
        if (!isMountedRef.current) return
        setIsLocating(false)
        const messages: Record<number, string> = {
          [error.PERMISSION_DENIED]: 'دسترسی به موقعیت مکانی رد شد',
          [error.POSITION_UNAVAILABLE]: 'موقعیت مکانی در دسترس نیست',
          [error.TIMEOUT]: 'زمان دریافت موقعیت به پایان رسید',
        }
        setLocationError(messages[error.code] || 'خطا در دریافت موقعیت مکانی')
      },
      options
    )
  }, [selectedLocation])

  // ===============================
  // Handle Map Click (Stable Reference)
  // ===============================
  const handleMapClick = useCallback((lat: number, lng: number) => {
    if (disabled) return
    setSelectedLocation({ lat, lng })
    onLocationSelectRef.current(lat, lng)
    reverseGeocode(lat, lng)
  }, [disabled])

  // ===============================
  // Reverse Geocode (Coordinates → Address)
  // ===============================
  const reverseGeocode = useCallback(async (lat: number, lng: number) => {
    reverseAbortControllerRef.current?.abort()
    const controller = new AbortController()
    reverseAbortControllerRef.current = controller

    try {
      const response = await fetchWithTimeout(
        `${NOMINATIM_REVERSE_URL}?format=json&lat=${lat}&lon=${lng}&accept-language=fa`,
        5000,
        { signal: controller.signal },
      )

      if (response.ok) {
        const data = await response.json()
        if (
          isMountedRef.current &&
          reverseAbortControllerRef.current === controller &&
          data.display_name
        ) {
          setSearchQuery(data.display_name)
        }
        return
      }

      throw new Error('Reverse geocode unavailable')
    } catch (error: unknown) {
      if (controller.signal.aborted) return

      if (mapProvider === 'neshan') {
        const apiKey = process.env.NEXT_PUBLIC_NESHAN_API_KEY
        if (apiKey) {
          try {
            const response = await fetchWithTimeout(
              `https://api.neshan.org/v2/reverse?lat=${lat}&lng=${lng}`,
              4000,
              {
                signal: controller.signal,
                headers: { 'Api-Key': apiKey },
              },
            )
            if (response.ok) {
              const data = await response.json()
              if (
                isMountedRef.current &&
                reverseAbortControllerRef.current === controller &&
                data.formatted_address
              ) {
                setSearchQuery(data.formatted_address)
              }
            }
          } catch {
            // شکست reverse geocode مانع انتخاب مختصات نمی‌شود.
          }
        }
      }
    } finally {
      if (reverseAbortControllerRef.current === controller) {
        reverseAbortControllerRef.current = null
      }
    }
  }, [mapProvider])

  // ===============================
  // Search Address (Nominatim)
  // ===============================
  const searchWithNeshan = useCallback(async (
    query: string,
    signal: AbortSignal,
  ) => {
    const apiKey = process.env.NEXT_PUBLIC_NESHAN_API_KEY
    if (!apiKey || apiKey === 'YOUR_API_KEY' || signal.aborted) return

    try {
      const response = await fetchWithTimeout(
        `https://api.neshan.org/v1/search?term=${encodeURIComponent(query)}&lat=${DEFAULT_CENTER.lat}&lng=${DEFAULT_CENTER.lng}`,
        5000,
        {
          signal,
          headers: { 'Api-Key': apiKey },
        },
      )

      if (response.ok && !signal.aborted) {
        const data = await response.json()
        if (isMountedRef.current && Array.isArray(data.items)) {
          const results: AddressSuggestion[] = data.items.map((item: any) => ({
            address: item.title || item.address || '',
            location: {
              lat: item.location?.y || 0,
              lng: item.location?.x || 0,
            },
          }))
          setSearchResults(results)
          setShowSearchResults(results.length > 0)
        }
      }
    } catch {
      if (!signal.aborted && isMountedRef.current) {
        setSearchResults([])
        setShowSearchResults(false)
      }
    }
  }, [])

  const searchAddress = useCallback(async (query: string) => {
    if (query.length < 3) {
      abortControllerRef.current?.abort()
      setSearchResults([])
      setShowSearchResults(false)
      setIsSearching(false)
      return
    }

    abortControllerRef.current?.abort()
    const controller = new AbortController()
    abortControllerRef.current = controller
    setIsSearching(true)

    try {
      const params = new URLSearchParams({
        format: 'json',
        q: query,
        limit: '5',
        countrycodes: 'ir',
        'accept-language': 'fa',
      })

      const response = await fetch(`${NOMINATIM_SEARCH_URL}?${params}`, {
        signal: controller.signal,
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`)
      }

      const data = await response.json()
      if (
        isMountedRef.current &&
        abortControllerRef.current === controller &&
        Array.isArray(data)
      ) {
        const results: AddressSuggestion[] = data.map((item: any) => ({
          address: item.display_name,
          location: {
            lat: Number.parseFloat(item.lat),
            lng: Number.parseFloat(item.lon),
          },
        }))
        setSearchResults(results)
        setShowSearchResults(results.length > 0)
      }
    } catch (error: unknown) {
      if (!controller.signal.aborted && mapProvider === 'neshan') {
        await searchWithNeshan(query, controller.signal)
      }
    } finally {
      // Request قدیمی نباید spinner درخواست جدیدتر را خاموش کند.
      if (isMountedRef.current && abortControllerRef.current === controller) {
        setIsSearching(false)
        abortControllerRef.current = null
      }
    }
  }, [mapProvider, searchWithNeshan])

  // ===============================
  // Select Address from Search Results
  // ===============================
  const handleSelectAddress = useCallback((suggestion: AddressSuggestion) => {
    setSelectedLocation(suggestion.location)
    setSearchQuery(suggestion.address)
    setSearchResults([])
    setShowSearchResults(false)
    onLocationSelectRef.current(
      suggestion.location.lat,
      suggestion.location.lng,
      suggestion.address
    )
    searchInputRef.current?.blur()
  }, [])

  // ===============================
  // Clear Search
  // ===============================
  const handleClearSearch = useCallback(() => {
    setSearchQuery('')
    setSearchResults([])
    setShowSearchResults(false)
    searchInputRef.current?.focus()
  }, [])

  // ===============================
  // Debounced Search
  // ===============================
  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery) {
        searchAddress(searchQuery)
      } else {
        setSearchResults([])
        setShowSearchResults(false)
      }
    }, SEARCH_DEBOUNCE_MS)

    return () => clearTimeout(timer)
  }, [searchQuery, searchAddress])

  // ===============================
  // Close search results on click outside
  // ===============================
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (showSearchResults && !target.closest(`.${styles.searchBar}`)) {
        setShowSearchResults(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [showSearchResults])

  // ===============================
  // Retry loading map
  // ===============================
  const handleRetryMap = useCallback(() => {
    setMapError(null)
    setMapProvider(null)
    // Re-trigger detection
    const detectMapProvider = async () => {
      try {
        const response = await fetchWithTimeout(OSM_TILE_URL, 4000)
        if (isMountedRef.current && response.ok) {
          setMapProvider('leaflet')
          return
        }
        throw new Error('OSM not available')
      } catch {
        if (isMountedRef.current) {
          const apiKey = process.env.NEXT_PUBLIC_NESHAN_API_KEY
          if (apiKey && apiKey !== 'YOUR_API_KEY') {
            setMapProvider('neshan')
          } else {
            setMapError('نقشه در دسترس نیست.')
          }
        }
      }
    }
    detectMapProvider()
  }, [])

  // ===============================
  // Computed Values
  // ===============================
  const mapCenter = selectedLocation || currentLocation || DEFAULT_CENTER

  // ===============================
  // Render
  // ===============================
  return (
    <div className={`${styles.mapPicker} ${disabled ? styles.disabled : ''}`}>
      {/* Search Bar */}
      {showSearch && (
        <div className={styles.searchBar}>
          <div className={styles.searchInputWrapper}>
            <Search size={18} className={styles.searchIcon} />
            <input
              ref={searchInputRef}
              type="text"
              className={styles.searchInput}
              placeholder={placeholder}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onFocus={() => searchResults.length > 0 && setShowSearchResults(true)}
              disabled={disabled}
            />
            {searchQuery && (
              <button
                type="button"
                className={styles.clearSearchBtn}
                onClick={handleClearSearch}
                aria-label="پاک کردن جستجو"
              >
                <X size={16} />
              </button>
            )}
            {isSearching && (
              <Loader2 size={18} className={styles.searchingIcon} />
            )}
          </div>

          {/* Search Results Dropdown */}
          {showSearchResults && searchResults.length > 0 && (
            <div className={styles.searchResults}>
              {searchResults.map((result, index) => (
                <button
                  key={index}
                  type="button"
                  className={styles.searchResultItem}
                  onClick={() => handleSelectAddress(result)}
                >
                  <MapPin size={16} className={styles.resultIcon} />
                  <span className={styles.resultText}>{result.address}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Toolbar */}
      {/* <div className={styles.toolbar}>
        {showCurrentLocation && (
          <button
            type="button"
            className={styles.locateBtn}
            onClick={getCurrentLocation}
            disabled={isLocating || disabled}
            title="موقعیت فعلی من"
          >
            {isLocating ? (
              <>
                <Loader2 size={16} className={styles.spinning} />
                <span>در حال دریافت...</span>
              </>
            ) : (
              <>
                <Navigation size={16} />
                <span>موقعیت فعلی</span>
              </>
            )}
          </button>
        )}

        {selectedLocation && (
          <div className={styles.coordinates}>
            <MapPin size={14} />
            <code>
              {selectedLocation.lat.toFixed(6)}, {selectedLocation.lng.toFixed(6)}
            </code>
          </div>
        )}
      </div> */}

      {/* Location Error */}
      {locationError && (
        <div className={styles.errorBar}>
          <AlertTriangle size={16} />
          <span>{locationError}</span>
          <button
            type="button"
            onClick={() => setLocationError(null)}
            className={styles.dismissError}
            aria-label="بستن"
          >
            <X size={16} />
          </button>
        </div>
      )}

      {/* Map Container */}
      {!mapError ? (
        <div className={styles.mapContainer} style={{ height }}>
          {mapProvider === 'leaflet' && (
            <LeafletMapWrapper
              center={mapCenter}
              marker={selectedLocation}
              onMapClick={handleMapClick}
            />
          )}

          {mapProvider === 'neshan' && (
            <NeshanMapWrapper
              center={mapCenter}
              marker={selectedLocation}
              onMapClick={handleMapClick}
            />
          )}

          {!mapProvider && <MapLoadingFallback />}
        </div>
      ) : (
        /* Map Error State */
        <div className={styles.mapErrorState} style={{ height }}>
          <AlertTriangle size={48} className={styles.mapErrorIcon} />
          <p className={styles.mapErrorText}>{mapError}</p>
          <button
            type="button"
            className={styles.mapRetryBtn}
            onClick={handleRetryMap}
          >
            تلاش مجدد
          </button>
        </div>
      )}

      {/* Hint */}

    </div>
  )
}, (prevProps, nextProps) => {
  // Custom comparison for memo
  return (
    prevProps.initialLocation?.lat === nextProps.initialLocation?.lat &&
    prevProps.initialLocation?.lng === nextProps.initialLocation?.lng &&
    prevProps.height === nextProps.height &&
    prevProps.showSearch === nextProps.showSearch &&
    prevProps.showCurrentLocation === nextProps.showCurrentLocation &&
    prevProps.disabled === nextProps.disabled &&
    prevProps.placeholder === nextProps.placeholder
  )
})

