'use client'

import React, { useEffect, useRef, useState } from 'react'
import { IconButton, Badge } from '@mui/material'
import {
  IconShoppingCart,
  IconUser,
  IconLogout,
  IconSettings,
  IconPackage,
  IconHeart,
  IconMapPin,
} from '@tabler/icons-react'
import { useRouter } from 'next/navigation'
import styles from './HeaderAction.module.scss'

import {
  useFloating,
  autoUpdate,
  offset,
  flip,
  shift,
  useDismiss,
  useRole,
  useInteractions,
  FloatingPortal,
  useTransitionStyles,
  FloatingArrow,
  arrow,
  type Placement,
} from '@floating-ui/react'

import { fetchMyCart } from '@/store/feature/cart/cartThunks'
import { getMeThunk, logoutThunk } from '@/store/feature/auth/authThunks'
import CartDropdown from '@/features/cart/components/CartDropdown/CartDropdown'
import { useAppDispatch, useAppSelector } from '@/store/hooks'
import { getUserSnapshot } from '@/services/api/common/authTokenStorage'

/* -------------------------------------------------------------------------- */
/* FloatingDropdown                                                           */
/* -------------------------------------------------------------------------- */

interface FloatingDropdownProps {
  anchorEl: HTMLElement
  onClose: () => void
  children: React.ReactNode
  placement?: Placement
}

const FloatingDropdown = ({
  anchorEl,
  onClose,
  children,
  placement = 'bottom-end',
}: FloatingDropdownProps) => {
  const arrowRef = useRef<SVGSVGElement>(null)
  const { refs, floatingStyles, context } = useFloating({
    open: true,
    strategy: 'fixed',
    elements: {
      reference: anchorEl,
    },
    onOpenChange: (open) => {
      if (!open) onClose()
    },
    placement,
    whileElementsMounted: autoUpdate,
    middleware: [
      // ✅ crossAxis حذف شد تا در موبایل مدال از آیکون جدا نشود
      offset({
        mainAxis: 16, // فاصله عمودی از دکمه
      }),
      flip({ fallbackAxisSideDirection: 'end' }),
      shift({ padding: 16 }), // ✅ حاشیه امن 16 پیکسلی از لبه‌های صفحه در موبایل
      arrow({
        element: arrowRef,
        padding: 12, // جلوگیری از چسبیدن فلش به گوشه‌های گرد مدال
      }),
    ],
  })

  const dismiss = useDismiss(context)
  const role = useRole(context)
  const { getFloatingProps } = useInteractions([dismiss, role])

  const { isMounted, styles: transitionStyles } = useTransitionStyles(context, {
    duration: 200,
    initial: {
      opacity: 0,
      transform: 'translateY(-8px)',
    },
  })

  if (!isMounted) return null

  return (
    <FloatingPortal root={document.body}>
      <div
        ref={refs.setFloating}
        style={{ ...floatingStyles, zIndex: 20000 }} // بالاتر از هدر، مگامنو و نتایج جستجو
        className={styles.dropdown}
        {...getFloatingProps()}
      >
        <div style={transitionStyles}>
          <FloatingArrow 
            ref={arrowRef} 
            context={context} 
            fill="#ffffff"
            width={14}
            height={7}
            style={{
              transform: 'translateY(-1px)' // رفع خطای بصری بین فلش و حاشیه مدال
            }}
          />
          <div className={styles.popoverPaper}>{children}</div>
        </div>
      </div>
    </FloatingPortal>
  )
}

/* -------------------------------------------------------------------------- */
/* HeaderAction                                                               */
/* -------------------------------------------------------------------------- */

const HeaderAction = () => {
  const router = useRouter()
  const dispatch = useAppDispatch()

  const { cart, loading: cartLoading } = useAppSelector(
    (state) => state.cart
  )
  const {
    token,
    isAuthenticated,
    initialized: authInitialized,
    userDetail,
    meLoading,
  } = useAppSelector((state) => state.auth)

  const [cartAnchorEl, setCartAnchorEl] =
    useState<HTMLButtonElement | null>(null)
  const [userAnchorEl, setUserAnchorEl] =
    useState<HTMLButtonElement | null>(null)
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false)
  const [snapshot] = useState(() => getUserSnapshot())
  const requestedMeTokenRef = useRef<string | null>(null)

  const displayUser = userDetail ?? snapshot

  useEffect(() => {
    if (!authInitialized) return
    void dispatch(fetchMyCart())
  }, [dispatch, authInitialized, isAuthenticated])

  useEffect(() => {
    if (!authInitialized || !isAuthenticated) return

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        dispatch(fetchMyCart())
      }
    }

    document.addEventListener('visibilitychange', handleVisibilityChange)

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange)
    }
  }, [dispatch, authInitialized, isAuthenticated])

  useEffect(() => {
    if (!token) {
      requestedMeTokenRef.current = null
      return
    }

    // ممکن است Token از storage بازیابی شده باشد اما snapshot کاربر وجود نداشته باشد.
    // برای هر token فقط یک درخواست خودکار می‌زنیم تا شکست getMe وارد retry-loop نشود.
    if (
      authInitialized &&
      isAuthenticated &&
      !userDetail &&
      !meLoading &&
      requestedMeTokenRef.current !== token
    ) {
      requestedMeTokenRef.current = token
      void dispatch(getMeThunk())
    }
  }, [dispatch, token, authInitialized, isAuthenticated, userDetail, meLoading])

  const closeAll = () => {
    setCartAnchorEl(null)
    setUserAnchorEl(null)
    setIsUserMenuOpen(false)
  }

  const handleUserClick = (
    event: React.MouseEvent<HTMLButtonElement>
  ) => {
    event.preventDefault()
    event.stopPropagation()

    // با باز شدن حساب کاربری، dropdown سبد خرید بسته شود.
    setCartAnchorEl(null)

    if (!isAuthenticated) {
      setIsUserMenuOpen(false)
      setUserAnchorEl(null)
      router.push('/login')
      return
    }

    // حتی اگر userDetail هنوز از Backend نرسیده باشد، منو باید باز شود.
    setUserAnchorEl(event.currentTarget)
    setIsUserMenuOpen((previous) => !previous)

    if (!userDetail && !meLoading) {
      void dispatch(getMeThunk())
    }
  }

  const handleLogout = async () => {
    closeAll()
    await dispatch(logoutThunk())
    router.push('/')
  }

  const getInitials = () => {
    if (displayUser?.firstName || displayUser?.lastName) {
      const firstInitial = displayUser.firstName ? displayUser.firstName.charAt(0) : ''
      const lastInitial = displayUser.lastName ? displayUser.lastName.charAt(0) : ''
      return `${firstInitial}${lastInitial}`.toUpperCase() || <IconUser size={24} stroke={1.5} />
    }
    return <IconUser size={24} stroke={1.5} />
  }

  const getUserDisplayInfo = () => {
    if (displayUser?.phoneNumber) return displayUser.phoneNumber
    if (displayUser?.email) return displayUser.email
    return meLoading ? 'در حال دریافت اطلاعات...' : 'اطلاعات تماس ثبت نشده'
  }

  const getUserDisplayName = () => {
    if (displayUser?.firstName || displayUser?.lastName) {
      return `${displayUser.firstName || ''} ${displayUser.lastName || ''}`.trim()
    }
    return meLoading ? 'در حال بارگذاری...' : 'کاربر عزیز'
  }

  return (
    <div className={styles.actionsContainer}>
      {/* ------------------------------- Cart -------------------------------- */}
      <IconButton
        aria-label="cart"
        onClick={(e) => {
          setIsUserMenuOpen(false)
          setUserAnchorEl(null)
          setCartAnchorEl(e.currentTarget)
        }}
        className={styles.iconButton}
      >
        <Badge badgeContent={cart?.totalItemsCount || 0} color="primary">
          <IconShoppingCart size={24} stroke={1.5} />
        </Badge>
      </IconButton>

      {cartAnchorEl && (
        <FloatingDropdown anchorEl={cartAnchorEl} onClose={closeAll} placement="bottom">
          <CartDropdown 
             cart={cart} 
             loading={cartLoading} 
             onClose={closeAll} 
          />
        </FloatingDropdown>
      )}

      {/* ------------------------------ User --------------------------------- */}
      <IconButton
        aria-label={isAuthenticated ? 'حساب کاربری' : 'ورود به حساب'}
        aria-haspopup={isAuthenticated ? 'menu' : undefined}
        aria-expanded={isAuthenticated ? isUserMenuOpen : undefined}
        onClick={handleUserClick}
        className={styles.iconButton}
        type="button"
      >
        <IconUser size={24} stroke={1.5} />
      </IconButton>

      {isAuthenticated && isUserMenuOpen && userAnchorEl && (
        <FloatingDropdown anchorEl={userAnchorEl} onClose={closeAll}>
          <div className={styles.popoverContentSmall}>

            <div className={styles.userInfoHeader}>
              <div className={styles.avatar}>
                {getInitials()}
              </div>
              <div className={styles.userDetails}>
                <div className={styles.userName}>
                  {getUserDisplayName()}
                </div>
                <div className={styles.userPhone}>
                  {getUserDisplayInfo()}
                </div>
              </div>
            </div>

            <div className={styles.divider}></div>

            <div className={styles.menuGroup}>
              <button
                className={styles.menuItem}
                onClick={() => {
                  closeAll()
                  router.push('/mechanics/dashboard')
                }}
              >
                <IconSettings size={20} stroke={1.5} />
                پنل مکانیک
              </button>

              <button
                className={styles.menuItem}
                onClick={() => {
                  closeAll()
                  router.push('/profile/orders')
                }}
              >
                <IconPackage size={20} stroke={1.5} />
                سفارش‌های من
              </button>

              <button
                className={styles.menuItem}
                onClick={() => {
                  closeAll()
                  router.push('/profile/wishlist')
                }}
              >
                <IconHeart size={20} stroke={1.5} />
                علاقه‌مندی‌ها
              </button>

              <button
                className={styles.menuItem}
                onClick={() => {
                  closeAll()
                  router.push('/profile/addresses')
                }}
              >
                <IconMapPin size={20} stroke={1.5} />
                آدرس‌ها
              </button>
            </div>

            <div className={styles.divider}></div>

            <div className={styles.menuGroup}>
              <button
                className={styles.menuItem}
                onClick={() => {
                  closeAll()
                  router.push('/profile')
                }}
              >
                <IconSettings size={20} stroke={1.5} />
                اطلاعات حساب کاربری
              </button>

              <button
                className={`${styles.menuItem} ${styles.danger}`}
                onClick={handleLogout}
              >
                <IconLogout size={20} stroke={1.5} />
                خروج از حساب
              </button>
            </div>

          </div>
        </FloatingDropdown>
      )}
    </div>
  )
}

export default HeaderAction

'use client'

import { useMemo, useState, useEffect } from 'react'
import type { Category } from '@/models/category/Category'
import { Link } from '@/components/common/Link/Link'
import styles from './DropdownMenu.module.scss'
import classNames from 'classnames'
import {
  Grid, Settings, Zap, CarFront, Activity, Disc, GitMerge, Droplet, Loader2
} from 'lucide-react'

import { useAppDispatch } from '@/store/hooks'
import { fetchSubCategories } from '@/store/feature/Category/categoryThunks'

type Props = {
  categories: Category[]
  isLoading?: boolean 
  error?: string | null
  onRetry?: () => void
}

const getDropdownIcon = (categoryId: number) => {
  switch (categoryId) {
    case 37: return <Settings size={18} />; 
    case 38: return <Zap size={18} />; 
    case 39: return <CarFront size={18} />; 
    case 40: return <Activity size={18} />; 
    case 41: return <Disc size={18} />; 
    case 42: return <GitMerge size={18} />; 
    case 43: return <Droplet size={18} />; 
    default: return <Grid size={18} />; 
  }
}

const DropdownMenu = ({ categories, isLoading, error, onRetry }: Props) => {
  const dispatch = useAppDispatch()

  const rootCategories = useMemo(
    () => categories.filter(c => !c.parentCategoryId || c.parentCategoryId === 0),
    [categories]
  )

  // 🟢 اصلاح مهم: به جای کل آبجکت، فقط ID دسته فعال را نگه می‌داریم
  const [activeId, setActiveId] = useState<number | null>(null)

  const [subLoading, setSubLoading] = useState(false)
  const [fetchedCategories, setFetchedCategories] = useState<Set<number>>(new Set())

  // 🟢 همیشه دسته فعال را به صورت زنده از داده‌های Redux می‌خوانیم تا اگر آپدیت شد، فوراً رندر شود
  const activeCategory = useMemo(() => {
    if (!activeId && rootCategories.length > 0) return rootCategories[0];
    return rootCategories.find(c => c.categoryId === activeId) || rootCategories[0];
  }, [activeId, rootCategories]);

  // 🟢 گوش دادن به تغییر دسته اکتیو و فراخوانی API
  useEffect(() => {
    if (activeCategory) {
      const catId = activeCategory.categoryId;
      const hasNoSubs = !activeCategory.subCategories || activeCategory.subCategories.length === 0;
      const notFetchedYet = !fetchedCategories.has(catId);

      if (hasNoSubs && notFetchedYet) {
        setSubLoading(true);
        dispatch(fetchSubCategories(catId))
          .unwrap()
          .finally(() => {
            setSubLoading(false);
            setFetchedCategories(prev => new Set(prev).add(catId));
          });
      }
    }
  }, [activeCategory, dispatch, fetchedCategories])

  function splitToColumns<T>(arr: T[]): T[][] {
    const mid = Math.ceil(arr.length / 2)
    return [arr.slice(0, mid), arr.slice(mid)]
  }

  if (error && categories.length === 0) {
    return <div className={styles.megaMenu} role="alert" style={{ padding: '2rem', textAlign: 'center' }}><span>{error}</span>{onRetry && <button type="button" onClick={onRetry}>تلاش دوباره</button>}</div>
  }

  if (isLoading || categories.length === 0) {
    return (
      <div className={styles.megaMenu} style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '3rem' }}>
        <Loader2 className="animate-spin" size={24} style={{ color: '#2563eb', marginLeft: '10px' }} />
        <span style={{ color: '#6b7280', fontSize: '16px' }}>در حال بارگذاری دسته‌بندی‌ها...</span>
      </div>
    )
  }

  return (
    <div className={styles.megaMenu}>
      {/* ستون اصلی */}
      <div className={styles.main}>
        {rootCategories.map(cat => (
          <div
            key={cat.categoryId}
            className={classNames(styles.mainItem, {
              [styles.active]: cat.categoryId === activeCategory?.categoryId
            })}
            onMouseEnter={() => setActiveId(cat.categoryId)}
          >
            <span className={styles.icon}>
              {getDropdownIcon(cat.categoryId)}
            </span>
            <span className={styles.label}>{cat.name}</span>
          </div>
        ))}
      </div>

      {/* بخش ساب کت ها */}
      <div className={styles.sub}>
        {subLoading ? (
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%', width: '100%' }}>
             <Loader2 className="animate-spin" size={24} style={{ color: '#2563eb', marginLeft: '10px' }} />
             <span style={{ color: '#6b7280', fontSize: '14px' }}>کمی صبر کنید...</span>
          </div>
        ) : (
          activeCategory?.subCategories?.map(sub => {
            const children = sub.subCategories ?? [];
            const limited = children.slice(0, 6);
            const [col1, col2] = splitToColumns(limited);

            return (
              <div className={styles.subWrapper} key={sub.categoryId}>
                <div className={styles.subTitle}>
                  <Link href={`/products/${sub.categoryId}`}>{sub.name}</Link>
                </div>

                <div className={styles.subContent}>
                  <div className={styles.subColumn}>
                    {col1.map(child => (
                      <Link
                        key={child.categoryId}
                        href={`/products/${child.categoryId}`}
                        className={styles.item}
                      >
                        {child.name}
                      </Link>
                    ))}
                  </div>

                  {col2.length > 0 && <span className={styles.verticalDivider} />}

                  <div className={styles.subColumn}>
                    {col2.map(child => (
                      <Link
                        key={child.categoryId}
                        href={`/products/${ child.categoryId}`}
                        className={styles.item}
                      >
                        {child.name}
                      </Link>
                    ))}
                  </div>
                </div>

                {/* مشاهده همه */}
                {children.length >= 0 && (
                  <Link
                    href={`/products/${sub.categoryId}`}
                    className={styles.viewAll}
                  >
                    مشاهده همه
                  </Link>
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

export default DropdownMenu

