import React, { useState, useEffect } from 'react'
import styles from './PriceRangeSlider.module.scss'
import { formatPrice, PRICE_ROUNDING_STEP, roundPrice } from '@/utils/price'

interface PriceRangeSliderProps {
  min: number
  max: number
  currentMin: number
  currentMax: number
  onChange: (min: number, max: number) => void
}

const PriceRangeSlider = ({ min, max, currentMin, currentMax, onChange }: PriceRangeSliderProps) => {
  const [localMin, setLocalMin] = useState(currentMin)
  const [localMax, setLocalMax] = useState(currentMax)

  useEffect(() => {
    setLocalMin(currentMin)
    setLocalMax(currentMax)
  }, [currentMin, currentMax])

  const handleMinChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(e.target.value)
    if (value <= localMax) {
      setLocalMin(value)
    }
  }

  const handleMaxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(e.target.value)
    if (value >= localMin) {
      setLocalMax(value)
    }
  }

  const handleApply = () => {
    onChange(roundPrice(localMin), roundPrice(localMax))
  }

  // ✅ جلوگیری از تقسیم بر صفر در صورتی که کمترین و بیشترین قیمت یکی باشد
  const rangeDiff = max - min === 0 ? 1 : max - min;
  const minPercent = ((localMin - min) / rangeDiff) * 100
  const maxPercent = ((localMax - min) / rangeDiff) * 100

  // استپ داینامیک برای راحتی حرکت اسلایدر روی مبالغ بالا
  const stepAmount = PRICE_ROUNDING_STEP;

  return (
    <div className={styles.container}>
      <div className={styles.labels}>
        <span>{formatPrice(localMin)} تومان</span>
        <span>{formatPrice(localMax)} تومان</span>
      </div>

      <div className={styles.sliderTrack}>
        <div className={styles.sliderFill} style={{
          right: `${minPercent}%`,
          left: `${100 - maxPercent}%`
        }} />
        <input
          type="range"
          min={min}
          max={max}
          step={stepAmount}
          value={localMin}
          onChange={handleMinChange}
          className={`${styles.slider} ${styles.sliderMin}`}
        />
        <input
          type="range"
          min={min}
          max={max}
          step={stepAmount}
          value={localMax}
          onChange={handleMaxChange}
          className={`${styles.slider} ${styles.sliderMax}`}
        />
      </div>

      <button onClick={handleApply} className={styles.applyBtn}>
        اعمال بازه قیمت
      </button>
    </div>
  )
}

export default PriceRangeSlider

'use client';

import { useState, useEffect } from 'react';
import { getMediaUrl } from '@/utils/media/getMediaUrl';
import Image from 'next/image';
import { useAppSelector } from '@/store/hooks'; 
import { selectProductDetails, selectDetailsLoading } from '@/store/feature/product/productSelectors'; 
import { Heart, Scale, ImageIcon, Loader2 } from 'lucide-react';
import styles from './ProductGallery.module.scss';
import { wishlistApi } from '@/features/wishlist/api/wishlistApi';
import { getAccessToken } from '@/services/api/common/authTokenStorage';
import type { Product } from '@/models/product/Product';
import type { ProductDetails } from '@/models/product/ProductDetails';

// تابع کمکی برای ساخت آدرس صحیح عکس
const getValidImageUrl = (rawUrl?: string) => getMediaUrl(rawUrl);

interface ProductGalleryProps {
  productOverride?: Product | ProductDetails;
}

export default function ProductGallery({ productOverride }: ProductGalleryProps = {}) {
  const selectedProduct = useAppSelector(selectProductDetails);
  const detailsLoading = useAppSelector(selectDetailsLoading);
  const product = productOverride ?? selectedProduct;
  const isLoading = productOverride ? false : detailsLoading;
  
  const [activeIndex, setActiveIndex] = useState(0);
  const [isFavorite, setIsFavorite] = useState(false);
  const [isWishlistLoading, setIsWishlistLoading] = useState(false);
  const [imageErrors, setImageErrors] = useState<Record<number, boolean>>({});

  // بررسی وضعیت علاقه‌مندی
  useEffect(() => {
    if (!product?.productId) return;

    const token = getAccessToken();

    if (token) {
      if ('isFavorite' in product) {
        setIsFavorite(Boolean((product as any).isFavorite));
      }
    } else {
      const guestWishlist = JSON.parse(localStorage.getItem('guest_wishlist') || '[]');
      setIsFavorite(guestWishlist.includes(product.productId));
    }
  }, [product]);

  if (isLoading) {
    return <div className={styles.skeletonGallery}></div>;
  }

  if (!product) {
    return null;
  }

  // 🔥 تبدیل images به آرایه (اگر string باشه از SSR)
  let images = 'images' in product ? product.images || [] : [];
  if (typeof images === 'string') {
    try {
      images = JSON.parse(images);
    } catch {
      images = [];
    }
  }
  
  if (!Array.isArray(images)) {
    images = [];
  }

  if (images.length === 0 && product.imageUrl) {
    images = [{
      imageId: 0,
      imageUrl: product.imageUrl,
      isMain: true,
      displayOrder: 0,
    }];
  }

  const currentImageRaw = images[activeIndex]?.imageUrl;
  const currentImage = getValidImageUrl(currentImageRaw);

  const handleWishlistToggle = async () => {
    if (!product.productId || isWishlistLoading) return;

    const token = getAccessToken();

    if (token) {
      setIsWishlistLoading(true);
      try {
        if (isFavorite) {
          await wishlistApi.removeFromWishlist(product.productId);
          setIsFavorite(false);
        } else {
          await wishlistApi.addToWishlist(product.productId);
          setIsFavorite(true);
        }
      } catch (error: any) {
        console.error('Wishlist API Error:', error);
      } finally {
        setIsWishlistLoading(false);
      }
    } 
    else {
      const guestWishlist = JSON.parse(localStorage.getItem('guest_wishlist') || '[]');
      
      if (isFavorite) {
        const updatedWishlist = guestWishlist.filter((id: number) => id !== product.productId);
        localStorage.setItem('guest_wishlist', JSON.stringify(updatedWishlist));
        setIsFavorite(false);
      } else {
        if (!guestWishlist.includes(product.productId)) {
          guestWishlist.push(product.productId);
          localStorage.setItem('guest_wishlist', JSON.stringify(guestWishlist));
        }
        setIsFavorite(true);
      }
    }
  };

  return (
    <div className={styles.galleryContainer}>
      <div className={styles.mainImageWrapper}>
        {/* دکمه‌های عملیات */}
        <div className={styles.actionIcons}>
          <button 
            className={styles.iconBtn} 
            aria-label="افزودن به علاقه‌مندی‌ها"
            onClick={handleWishlistToggle}
            disabled={isWishlistLoading}
          >
            {isWishlistLoading ? (
              <Loader2 size={20} className={styles.spinner} color="white" />
            ) : (
              <Heart 
                size={20} 
                strokeWidth={1.5} 
                color={isFavorite ? "#ef4444" : "white"} 
                fill={isFavorite ? "#ef4444" : "transparent"} 
              />
            )}
          </button>
          
          <div className={styles.iconDivider}></div>
          
          <button className={styles.iconBtn} aria-label="مقایسه">
            <Scale size={20} strokeWidth={1.5} color="white" />
          </button>
        </div>

        {/* تصویر اصلی */}
        <div className={styles.mainImage}>
          {currentImage && !imageErrors[activeIndex] ? (
            <Image
              src={currentImage}
              alt={product.productName || 'تصویر محصول'}
              fill
              sizes="(max-width: 768px) 100vw, 400px"
              className={styles.imageConfig}
              priority
              onError={() => {
                setImageErrors(prev => ({ ...prev, [activeIndex]: true }));
              }}
            />
          ) : (
            <div className={styles.noImageFallback}>
              <ImageIcon size={48} color="#64748b" />
              <p>تصویری موجود نیست</p>
            </div>
          )}
        </div>
      </div>

      {/* تصاویر بندانگشتی */}
      {images.length > 1 && (
        <div className={styles.thumbnailList}>
          {images.map((img: any, index: number) => {
            const thumbUrl = getValidImageUrl(img.imageUrl);
            
            return (
              <button
                key={img.imageId || index}
                className={`${styles.thumbnailItem} ${
                   activeIndex === index ? styles.activeThumbnail : ''
                }`}
                onClick={() => setActiveIndex(index)}
              >
                {thumbUrl ? (
                  <Image
                    src={thumbUrl}
                    alt={`${product.productName} - تصویر ${index + 1}`}
                    fill
                    sizes="80px"
                    className={styles.imageConfig}
                  />
                ) : (
                  <ImageIcon size={24} color="#ccc" />
                )}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Modal } from '@mui/material';
// اضافه کردن آیکون Trash2
import { X, CheckCircle2, Heart, Plus, Minus, Loader2, Trash2 } from 'lucide-react'; 
import styles from './ProductOverViewModal.module.scss';
import ProductGallery from '../ProductGallery/ProductGallery';

// Redux Imports
import { useDispatch, useSelector } from 'react-redux';
import { AppDispatch } from '@/store'; 
// اضافه کردن سلکتور و تانک‌های مربوط به آپدیت و حذف
import { addToCart, updateItemQuantity, removeCartItem } from '@/store/feature/cart/cartThunks'; 
import { selectCartActionLoading, selectCart } from '@/store/feature/cart/cartSelectors';
import { formatPrice, roundPrice } from '@/utils/price';

const ProductOverViewModal = (props: any) => {
    const { isOpen, modalClose, product } = props;

    // Redux Setup
    const dispatch = useDispatch<AppDispatch>();
    const actionLoading = useSelector(selectCartActionLoading);
    const cart = useSelector(selectCart); // دریافت سبد خرید از ریداکس

    // Local State for Quantity (فقط برای زمانی که محصول در سبد نیست)
    const [localQuantity, setLocalQuantity] = useState(1);

    if (!product) return null;

    // پیدا کردن محصول در سبد خرید ریداکس
    const cartItem = cart?.items?.find((item: any) => item.productId === product.productId);
    const isInCart = !!cartItem;

    const hasDiscount = product.productDiscount && product.productDiscount.isActive;
    let finalPrice = product.basePrice;

    if (hasDiscount && product.productDiscount) {
        const { discountType, discountValue } = product.productDiscount;
        finalPrice = discountType
            ? product.basePrice - (product.basePrice * discountValue / 100)
            : Math.max(0, product.basePrice - discountValue);
    }

    finalPrice = roundPrice(finalPrice);

    // ---- هندلرهای مربوط به حالت لوکال (محصول در سبد نیست) ----
    const handleLocalIncrease = () => setLocalQuantity(prev => prev + 1);
    const handleLocalDecrease = () => setLocalQuantity(prev => (prev > 1 ? prev - 1 : 1));

    const handleAddToCart = () => {
        dispatch(addToCart({ productId: product.productId, quantity: localQuantity }))
            .unwrap()
            .then(() => {
                // modalClose(); // اگه میخوای بعد از افزودن، مودال بسته نشه و حالت دکمه تغییر کنه، این خط رو کامنت کن
            })
            .catch((error) => console.error(error));
    };

    // ---- هندلرهای مربوط به حالت سبد خرید (محصول در سبد هست) ----
    const handleCartIncrease = () => {
        if (cartItem) {
            dispatch(updateItemQuantity({ cartItemId: cartItem.cartItemId, quantity: cartItem.quantity + 1 }));
        }
    };

    const handleCartDecreaseOrRemove = () => {
        if (cartItem) {
            if (cartItem.quantity > 1) {
                // اگر بیشتر از یکی بود، کم کن
                dispatch(updateItemQuantity({ cartItemId: cartItem.cartItemId, quantity: cartItem.quantity - 1 }));
            } else {
                // اگر ۱ بود، کلاً از سبد خرید حذف کن
                dispatch(removeCartItem(cartItem.cartItemId));
            }
        }
    };

    return (
        <Modal className={styles.container} open={isOpen} onClose={modalClose}>
            <div className={styles.contentContainer} dir="rtl">

                <button className={styles.closeBtn} onClick={modalClose}>
                    <X size={24} />
                </button>

                <div className={styles.gridContainer}>

                    {/* سمت راست: گالری عکس */}
                    <div className={styles.productGalleryContainer}>
                        <ProductGallery productOverride={product} />
                    </div>

                    {/* سمت چپ: اطلاعات محصول */}
                    <div className={styles.productInfoContainer}>

                        <h3 className={styles.title}>{product.productName}</h3>

                        <div className={styles.priceWrapper}>
                            {hasDiscount && (
                                <span className={styles.oldPrice}>
                                    {formatPrice(product.basePrice)}
                                </span>
                            )}
                            <span className={styles.priceValue}>
                                {formatPrice(finalPrice)} <span className={styles.currency}>تومان</span>
                            </span>
                        </div>

                        <div className={styles.metaInfo}>
                            <span className={styles.brand}>برند : {product.brandName || 'ایساکو'}</span>
                            {product.totalStock > 0 ? (
                                <span className={styles.hasProduct}>
                                    <CheckCircle2 size={16} /> موجود در انبار
                                </span>
                            ) : (
                                <span className={styles.notHasProduct}>ناموجود</span>
                            )}
                        </div>

                        <div className={styles.featuresBox}>
                            <h4>ویژگی های محصول:</h4>
                            <ul>
                                <li>جنس فلز</li>
                                <li>مناسب همه مدل های رانا</li>
                                <li>قابل استفاده در دنا</li>
                            </ul>
                        </div>

                        {/* ==================================================== */}
                        {/* ================ بخش مدیریت دکمه‌ها ================ */}
                        {/* ==================================================== */}

                        {isInCart ? (
                            // اگر محصول داخل سبد خرید بود:
                            <div className={styles.inCartActionContainer}>
                                <div className={styles.inCartHeader}>
                                    <span>در سبد خرید شما:</span>
                                    <span className={styles.totalPriceCart}>
                                        {formatPrice(roundPrice(cartItem.unitPrice) * cartItem.quantity)} تومان
                                    </span>
                                </div>
                                <div className={styles.cartQuantityControl}>
                                    <button onClick={handleCartIncrease} disabled={actionLoading}>
                                        <Plus size={20} />
                                    </button>

                                    <span className={styles.quantityNumber}>
                                        {actionLoading ? <Loader2 className={styles.spinner} size={20} /> : cartItem.quantity.toLocaleString('fa-IR')}
                                    </span>

                                    <button 
                                        onClick={handleCartDecreaseOrRemove} 
                                        disabled={actionLoading} 
                                        className={cartItem.quantity === 1 ? styles.trashBtn : ''}
                                    >
                                        {cartItem.quantity > 1 ? <Minus size={20} /> : <Trash2 size={20} />}
                                    </button>
                                </div>
                            </div>
                        ) : (
                            // اگر محصول در سبد خرید نبود (حالت پیش‌فرض):
                            <>
                                <div className={styles.quantityAction}>
                                    <span className={styles.quantityLabel}>تعداد:</span>
                                    <div className={styles.quantityControl}>
                                        <button onClick={handleLocalDecrease} disabled={localQuantity <= 1 || actionLoading}>
                                            <Minus size={16} />
                                        </button>
                                        <span className={styles.quantityNumber}>{localQuantity.toLocaleString('fa-IR')}</span>
                                        <button onClick={handleLocalIncrease} disabled={actionLoading}>
                                            <Plus size={16} />
                                        </button>
                                    </div>
                                </div>

                                <div className={styles.actionButtons}>
                                    <button 
                                        className={styles.addToCartBtn} 
                                        onClick={handleAddToCart}
                                        disabled={actionLoading || product.totalStock <= 0}
                                    >
                                        {actionLoading ? (
                                            <Loader2 className={styles.spinner} size={24} />
                                        ) : (
                                            'افزودن به سبد خرید'
                                        )}
                                    </button>

                                    <button className={styles.wishlistBtn}>
                                        <Heart size={24} />
                                    </button>
                                </div>
                            </>
                        )}

                        <div className={styles.viewFullProduct}>
                            <a href={`/product/${product.productId}`}>مشاهده کامل محصول &gt;</a>
                        </div>

                    </div>
                </div>
            </div>
        </Modal>
    );
};

export default ProductOverViewModal;

'use client'

import React from 'react'
import styles from './ProductTabs.module.scss'
import classNames from 'classnames'

interface Tab {
  id: string
  label: string
  content: React.ReactNode
}

interface ProductTabsProps {
  tabs: Tab[]
  defaultTab?: string
  activeTab: string
  onTabChange: (tabId: string) => void
}

const ProductTabs = ({ tabs, defaultTab, activeTab, onTabChange }: ProductTabsProps) => {
  return (
    <div className={styles.tabsContainer}>
      <div className={styles.tabHeader}>
        {tabs.map((tab) => (
          <button
            key={tab.id}
            className={classNames(styles.tabButton, {
              [styles.active]: activeTab === tab.id,
            })}
            onClick={() => onTabChange(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className={styles.tabContent}>
        {tabs.find((tab) => tab.id === activeTab)?.content}
      </div>
    </div>
  )
}

export default ProductTabs

// src/components/product/productCard/ProductCard.tsx

import React, { useEffect, useState } from 'react';
import { getMediaUrl } from '@/utils/media/getMediaUrl';
import OptimizedImage from '@/components/common/OptimizedImage/OptimizedImage';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Product } from '@/models/product/Product'; 
import { useAppDispatch, useAppSelector } from '@/store/hooks'; 
import { addToCart, updateItemQuantity, removeCartItem } from '@/store/feature/cart/cartThunks'; 
import { selectCart, selectCartActionLoading } from '@/store/feature/cart/cartSelectors'; 
import { Plus, Minus, Trash2, Loader2, ShoppingCart, Heart } from 'lucide-react';
import styles from './ProductCard.module.scss';
import ProductOverViewModal from '../ProductOverViewModal/ProductOverViewModal';
import { roundPrice } from '@/utils/price';
import toast from 'react-hot-toast'; // 🟢 اضافه شدن Toast
import { wishlistApi } from '@/features/wishlist/api/wishlistApi';
import { getAccessToken } from '@/services/api/common/authTokenStorage';

interface ProductCardProps {
  product: Product;
}

const formatPrice = (price: number): number => roundPrice(price);

const getValidImageUrl = (rawUrl?: string) => getMediaUrl(rawUrl);

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const router = useRouter();
  const dispatch = useAppDispatch();
  const currentImage = getValidImageUrl(product.imageUrl);

  const cart = useAppSelector(selectCart);
  const isGlobalCartLoading = useAppSelector(selectCartActionLoading);
  const [isAddingThisItem, setIsAddingThisItem] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isFavorite, setIsFavorite] = useState(Boolean((product as Product & { isFavorite?: boolean }).isFavorite));
  const [isWishlistLoading, setIsWishlistLoading] = useState(false);
  const [failedImage, setFailedImage] = useState<string | null>(null);

  useEffect(() => {
    const backendFavorite = (product as Product & { isFavorite?: boolean }).isFavorite;
    if (typeof backendFavorite === 'boolean') {
      setIsFavorite(backendFavorite);
      return;
    }

    if (!getAccessToken()) {
      const guestWishlist: number[] = JSON.parse(localStorage.getItem('guest_wishlist') || '[]');
      setIsFavorite(guestWishlist.includes(product.productId));
    }
  }, [product]);

  const cartItem = cart?.items?.find((item: any) => item.productId === product.productId);
  const isInCart = !!cartItem;
  const isOutOfStock = product.totalStock <= 0;

  const handleCardClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
    // ناموجودها هم باید صفحه‌ی کامل محصول را باز کنند تا کاربر بتواند
    // مشخصات و زمان تأمین را ببیند. مشاهده سریع فقط برای کالای موجود در
    // چیدمان موبایل استفاده می‌شود.
    if (!isOutOfStock && window.innerWidth <= 768) {
      event.preventDefault();
      setIsModalOpen(true);
    }
  };

  const handleWishlistToggle = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (isWishlistLoading) return;

    const previousValue = isFavorite;
    setIsFavorite(!previousValue);
    setIsWishlistLoading(true);

    try {
      if (getAccessToken()) {
        if (previousValue) await wishlistApi.removeFromWishlist(product.productId);
        else await wishlistApi.addToWishlist(product.productId);
      } else {
        const guestWishlist: number[] = JSON.parse(localStorage.getItem('guest_wishlist') || '[]');
        const nextWishlist = previousValue
          ? guestWishlist.filter((id) => id !== product.productId)
          : Array.from(new Set([...guestWishlist, product.productId]));
        localStorage.setItem('guest_wishlist', JSON.stringify(nextWishlist));
      }
      toast.success(previousValue ? 'از علاقه‌مندی‌ها حذف شد' : 'به علاقه‌مندی‌ها اضافه شد');
    } catch {
      setIsFavorite(previousValue);
      toast.error('تغییر علاقه‌مندی انجام نشد');
    } finally {
      setIsWishlistLoading(false);
    }
  };

  const handleAddToCart = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (isOutOfStock) {
      router.push(`/product/${product.productId}`);
      return;
    }
    if (isGlobalCartLoading) return;

    setIsAddingThisItem(true);
    try {
      await dispatch(addToCart({ productId: product.productId, quantity: 1 })).unwrap();
      toast.success('محصول با موفقیت به سبد خرید اضافه شد', { duration: 3000 }); // 🟢 پیام موفقیت
    } catch (error) {
      toast.error(error as string, { duration: 4000 }); // 🟢 نمایش ارور به صورت پاپ‌آپ موقت
    } finally {
      setIsAddingThisItem(false);
    }
  };

  const handleIncrease = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (cartItem && !isGlobalCartLoading) {
      try {
        await dispatch(updateItemQuantity({ cartItemId: cartItem.cartItemId, quantity: cartItem.quantity + 1 })).unwrap();
      } catch (error) {
        toast.error(error as string, { duration: 4000 }); // 🟢
      }
    }
  };

  const handleDecreaseOrRemove = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (cartItem && !isGlobalCartLoading) {
      try {
        if (cartItem.quantity > 1) {
          await dispatch(updateItemQuantity({ cartItemId: cartItem.cartItemId, quantity: cartItem.quantity - 1 })).unwrap();
        } else {
          await dispatch(removeCartItem(cartItem.cartItemId)).unwrap();
          toast.success('محصول از سبد خرید حذف شد', { duration: 3000 });
        }
      } catch (error) {
        toast.error(error as string, { duration: 4000 }); // 🟢
      }
    }
  };

  const basePriceFormatted = formatPrice(product.basePrice);
  const hasDiscount = product.productDiscount && product.productDiscount.isActive;
  let finalPriceFormatted = basePriceFormatted;
  let discountLabel = null;

  if (hasDiscount && product.productDiscount) {
    const { discountType, discountValue } = product.productDiscount;
    if (discountType) {
      const calculatedFinalPrice = product.basePrice - (product.basePrice * discountValue / 100);
      finalPriceFormatted = formatPrice(calculatedFinalPrice);
      discountLabel = `${discountValue.toLocaleString('fa-IR')}٪`;
    } else {
      const calculatedFinalPrice = product.basePrice - discountValue;
      finalPriceFormatted = formatPrice(calculatedFinalPrice > 0 ? calculatedFinalPrice : 0);
    }
  }

  return (
    <>
      <Link
        className={styles.card}
        href={`/product/${product.productId}`}
        onClick={handleCardClick}
        dir="rtl"
      >
        <div className={styles.link}>
          <div className={styles.imageWrapper}>
            <button
              type="button"
              className={styles.quickViewBtn}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                setIsModalOpen(true);
              }}
            >
              مشاهده سریع
            </button>
            <button
              type="button"
              className={`${styles.favoriteBtn} ${isFavorite ? styles.favoriteActive : ''}`}
              aria-label={isFavorite ? 'حذف از علاقه‌مندی‌ها' : 'افزودن به علاقه‌مندی‌ها'}
              aria-pressed={isFavorite}
              disabled={isWishlistLoading}
              onClick={handleWishlistToggle}
            >
              {isWishlistLoading
                ? <Loader2 size={19} className={styles.spinnerIcon} />
                : <Heart size={19} fill={isFavorite ? 'currentColor' : 'none'} />}
            </button>
            {hasDiscount && discountLabel && !isOutOfStock && (
              <span className={styles.discountBadge}>{discountLabel}</span>
            )}
            
            {currentImage && failedImage !== currentImage ? (
              <OptimizedImage 
                src={currentImage} 
                alt={product.productName} 
                className={`${styles.productImage} ${isOutOfStock ? styles.grayscale : ''}`} 
                draggable={false} 
                width={480}
                height={480}
                sizes="(max-width: 640px) 45vw, (max-width: 1024px) 25vw, 220px"
                onError={() => setFailedImage(currentImage)}
              />
            ) : (
              <span className={styles.placeholder}>بدون تصویر</span>
            )}
            
            {isOutOfStock && (
              <span className={styles.outOfStockBadge}>ناموجود</span>
            )}
          </div>
          
          <h3 className={styles.title} title={product.productName}>
            {product.productName}
          </h3>
        </div>

        <div className={styles.footer}>
          <div className={styles.priceWrapper}>
            {!isOutOfStock && hasDiscount && (
              <span className={styles.oldPrice}>{basePriceFormatted.toLocaleString('fa-IR')}</span>
            )}
            <span className={styles.priceValue}>
               {isOutOfStock ? (
                 <span className={styles.outOfStockText}>ناموجود</span>
               ) : (
                 <>
                   {finalPriceFormatted.toLocaleString('fa-IR')} <span className={styles.currency}>تومان</span>
                 </>
               )}
            </span>
          </div>

          <div className={styles.cartActionWrapper}>
            {!isInCart ? (
              <button 
                className={`${styles.cartBtn} ${isOutOfStock ? styles.disabledBtn : ''}`} 
                onClick={handleAddToCart}
                disabled={isAddingThisItem}
              >
                {isAddingThisItem ? (
                  <Loader2 className={styles.spinnerIcon} size={18} />
                ) : (
                  <ShoppingCart size={18} strokeWidth={2.5} />
                )}
              </button>
            ) : (
              <div className={styles.cartControls} onClick={(e) => { e.preventDefault(); e.stopPropagation(); }}>
                <button onClick={handleIncrease} disabled={isGlobalCartLoading} className={styles.controlBtn}>
                  <Plus size={14} strokeWidth={3} />
                </button>
                <span className={styles.quantityNumber}>
                  {isGlobalCartLoading ? <Loader2 className={styles.spinnerIconSmall} size={14} /> : cartItem.quantity.toLocaleString('fa-IR')}
                </span>
                <button onClick={handleDecreaseOrRemove} disabled={isGlobalCartLoading} className={`${styles.controlBtn} ${cartItem.quantity === 1 ? styles.danger : ''}`}>
                  {cartItem.quantity > 1 ? <Minus size={14} strokeWidth={3} /> : <Trash2 size={14} strokeWidth={2.5} />}
                </button>
              </div>
            )}
          </div>
        </div>
      </Link>

      <ProductOverViewModal 
        isOpen={isModalOpen} 
        modalClose={() => setIsModalOpen(false)} 
        product={product} 
      />
    </>
  );
};

export default ProductCard;

'use client'

import React, { useEffect, useState } from 'react'
import { useAppDispatch, useAppSelector } from '@/store/hooks'
import { fetchMyProfile, updateProfile } from '@/store/feature/profile/profileThunks'
import { 
  selectProfile, 
  selectProfileUpdating, 
  selectProfileError, 
  selectProfileSuccessMessage 
} from '@/store/feature/profile/profileSelectors'
import { clearProfileMessages } from '@/store/feature/profile/profileSlice'
import styles from './ProfileInfo.module.scss'
import { IconCheck } from '@tabler/icons-react'
import BackToSidebar from '../BackToSidebar/BackToSidebar'
import JalaliDatePicker from '@/components/common/JalaliDatePicker/JalaliDatePicker'

const ProfileInfo = () => {
  const dispatch = useAppDispatch()
  const profile = useAppSelector(selectProfile)
  const updating = useAppSelector(selectProfileUpdating)
  const error = useAppSelector(selectProfileError)
  const successMessage = useAppSelector(selectProfileSuccessMessage)

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phoneNumber: '',
    gender: '',
    birthDate: '',
    bio: '',
  })

  // دریافت پروفایل هنگام mount
  useEffect(() => {
    dispatch(fetchMyProfile())
  }, [dispatch])

  // پر کردن فرم بعد از دریافت داده
  useEffect(() => {
    if (profile) {
      setFormData({
        firstName: profile.firstName || profile.userProfile?.firstName || '',
        lastName: profile.lastName || profile.userProfile?.lastName || '',
        email: profile.email || '',
        phoneNumber: profile.phoneNumber || '',
        gender: profile.gender || profile.userProfile?.gender || '',
        birthDate: profile.birthDate || profile.userProfile?.birthDate?.split('T')[0] || '',
        bio: profile.bio || profile.userProfile?.bio || '',
      })
    }
  }, [profile])

  // پاک کردن پیام‌ها بعد از ۳ ثانیه
  useEffect(() => {
    if (successMessage || error) {
