'use client';

import { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useDebounce } from '@/features/search/hooks/useDebounce';
import styles from './SearchAutocomplete.module.scss';
import { Search, TrendingUp, ChevronLeft } from 'lucide-react';
import { SearchSuggestion } from "@/models/search/SearchSuggestion";

import { searchApi } from '@/features/search/api/routes';
import { useBodyScrollLock } from '@/hooks/useBodyScrollLock';

export default function SearchAutocomplete() {
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const debouncedQuery = useDebounce(query, 500);
  const normalizedDebouncedQuery = debouncedQuery.trim();
  const inputRef = useRef<HTMLInputElement>(null);
  const pathname = usePathname();
  const router = useRouter();
  const prevPathname = useRef(pathname);

  // بستن دراپ‌دان هنگام تغییر مسیر
  useEffect(() => {
    if (prevPathname.current !== pathname) {
      setIsOpen(false);
      setQuery('');
      setSuggestions([]);
      prevPathname.current = pathname;
    }
  }, [pathname]);

  // 🟢 جستجو با تاخیر و کنترل دقیق چرخه حیات (رفع Memory Leak و Race Condition)
  useEffect(() => {
    const controller = new AbortController();
    let isMounted = true; 

    if (normalizedDebouncedQuery.length > 2) {
      setIsLoading(true);

      // 🟢 اصلاح شد: فراخوانی متد getSuggestions از داخل آبجکت searchApi
      searchApi.getSuggestions(normalizedDebouncedQuery, controller.signal)
        .then((data: any) => {
          if (isMounted) {
            setSuggestions(data || []);
            setIsLoading(false);
          }
        })
        .catch(() => {
          if (isMounted) {
            setSuggestions([]);
            setIsLoading(false);
          }
        });

    } else {
      setSuggestions([]);
      setIsLoading(false);
    }

    return () => {
      isMounted = false; 
      controller.abort();
    };
  }, [normalizedDebouncedQuery]);

  // قفل شمارنده‌دار؛ cleanup یک overlay دیگر را باز نمی‌کند.
  useBodyScrollLock(isOpen);

  const openDropdown = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setIsOpen(true);
    setTimeout(() => inputRef.current?.focus(), 0);
  };

  return (
    <div className={`${styles.searchContainer} ${isOpen ? styles.activeContainer : ''}`}>

      {isOpen && (
        <div
          className={styles.overlay}
          onClick={(e) => {
            e.stopPropagation();
            setIsOpen(false);
          }}
        />
      )}

      <div
        className={`${styles.searchBox} ${isOpen ? styles.active : ''}`}
        onClick={openDropdown}
      >
        <Search className={styles.searchIcon} />
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={e => setQuery(e.target.value)}
          onFocus={() => setIsOpen(true)}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && query.trim().length >= 2) {
              event.preventDefault();
              setIsOpen(false);
              router.push(`/search?q=${encodeURIComponent(query.trim())}`);
            }
            if (event.key === 'Escape') setIsOpen(false);
          }}
          placeholder="جستجوی نام یا کد قطعه..."
          className={isOpen ? styles.inputOpen : styles.input}
        />
      </div>

      {isOpen && (
        <div className={styles.dropdown}>
          {query.trim().length === 0 && (
            <div className={styles.defaultState}>
              <div className={styles.sectionHeader}>
                <TrendingUp size={16} />
                <span>جستجوهای پرطرفدار</span>
              </div>
              <div className={styles.popularTags}>
                <span className={styles.tag}>لنت ترمز ۲۰۶</span>
                <span className={styles.tag}>تسمه تایم ال ۹۰</span>
                <span className={styles.tag}>شمع موتور بوش</span>
                <span className={styles.tag}>روغن موتور الف</span>
              </div>
              <div className={styles.divider} />
              <div className={styles.sectionHeader}>
                <span>دسته‌بندی‌های محبوب</span>
              </div>
              <ul className={styles.popularCategories}>
                <li>
                  <Link href="/category/brakes" onClick={() => setIsOpen(false)}>
                    سیستم ترمز <ChevronLeft size={14}/>
                  </Link>
                </li>
                <li>
                  <Link href="/category/engine" onClick={() => setIsOpen(false)}>
                    قطعات موتوری <ChevronLeft size={14}/>
                  </Link>
                </li>
                <li>
                  <Link href="/category/filters" onClick={() => setIsOpen(false)}>
                    فیلتر و روغن <ChevronLeft size={14}/>
                  </Link>
                </li>
              </ul>
            </div>
          )}

          {query.trim().length > 0 && isLoading && (
            <div className={styles.statusMessage}>
              <div className={styles.spinner} />
              <span>در حال جستجوی "{query}"...</span>
            </div>
          )}

          {query.trim().length > 0 && !isLoading && suggestions.length > 0 && (
            <div className={styles.resultsList}>
              {suggestions.map((item, index) => (
                <Link
                  href={`/${item.type}/${item.slug}`}
                  key={`suggestion-${item.type}-${item.id}-${index}`}
                  className={styles.suggestionItem}
                  onClick={() => setIsOpen(false)}
                >
                  <div className={styles.itemInfo}>
                    <span className={styles.itemName}>{item.title}</span>
                    {item.partNumber && (
                      <span className={styles.itemMeta}>کد: {item.partNumber}</span>
                    )}
                  </div>
                </Link>
              ))}
            </div>
          )}

          {query.trim().length > 2 && !isLoading && suggestions.length === 0 && (
            <div className={styles.statusMessage}>
              قطعه‌ای یافت نشد.
            </div>
          )}
          {query.trim().length >= 2 && !isLoading && (
            <Link className={styles.allResults} href={`/search?q=${encodeURIComponent(query.trim())}`} onClick={() => setIsOpen(false)}>
              مشاهده همه نتایج برای «{query.trim()}»
            </Link>
          )}
        </div>
      )}
    </div>
  );
}

import { SearchSuggestion } from "@/models/search/SearchSuggestion";
import { browserApiUrl } from '@/config/runtime';

let abortController: AbortController | null = null;

export const fetchSuggestions = async (query: string): Promise<SearchSuggestion[]> => {
  if (abortController) {
    abortController.abort();
  }
  abortController = new AbortController();

  const url = `${browserApiUrl}/search/suggestions?q=${encodeURIComponent(query)}&limit=5`;

  try {
    const res = await fetch(url, {
      signal: abortController.signal,
      headers: { 'Content-Type': 'application/json' }
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data: SearchSuggestion[] = await res.json();
    return data;
  } catch (err: any) {
    if (err.name === 'AbortError') {
      return [];
    }
    console.error('fetchSuggestions error:', err);
    return [];
  }
};

'use client';

import React, { useState, useRef, useEffect } from 'react';
import styles from './HeroSearch.module.scss';
import { useHeroSearch } from './useHeroSearch';
import { Search, ChevronDown } from 'lucide-react';

interface Option {
  value: string | number;
  label: string;
}

interface SearchableSelectProps {
  options: Option[];
  value: string | number;
  onChange: (val: string | number) => void;
  placeholder: string;
  disabled?: boolean;
}

const SearchableSelect: React.FC<SearchableSelectProps> = ({ options, value, onChange, placeholder, disabled }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredOptions = options.filter(opt => 
    opt.label.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const selectedOption = options.find(opt => String(opt.value) === String(value));

  return (
    <div className={styles.customSelectWrapper} ref={wrapperRef}>
      <div 
        className={`${styles.customSelectHeader} ${disabled ? styles.disabled : ''} ${isOpen ? styles.active : ''}`}
        onClick={() => !disabled && setIsOpen(!isOpen)}
      >
        <span className={selectedOption ? styles.selectedText : styles.placeholderText}>
          {selectedOption ? selectedOption.label : placeholder}
        </span>
        <ChevronDown size={18} className={`${styles.chevron} ${isOpen ? styles.open : ''}`} />
      </div>

      {isOpen && (
        <div className={styles.customSelectList}>
          <div className={styles.searchBox}>
            <Search size={16} className={styles.searchIcon} />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="جستجو..."
              onClick={(e) => e.stopPropagation()}
              autoFocus
            />
          </div>
          <ul className={styles.optionsList}>
            {filteredOptions.length > 0 ? (
              filteredOptions.map(opt => (
                <li
                  key={opt.value}
                  className={`${styles.optionItem} ${String(opt.value) === String(value) ? styles.selected : ''}`}
                  onClick={() => { 
                    onChange(opt.value); 
                    setIsOpen(false); 
                    setSearchTerm(''); 
                  }}
                >
                  {opt.label}
                </li>
              ))
            ) : (
              <li className={styles.noResult}>موردی یافت نشد</li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
};

export default function HeroSearch() {
  const {
    categories,
    makes,
    models,
    selectedCategory,
    setSelectedCategory,
    selectedMake,
    setSelectedMake,
    selectedModel,
    setSelectedModel,
    handleSearch
  } = useHeroSearch();

  const mainCategories = categories
    .filter(cat => !cat.parentCategoryId || cat.parentCategoryId === 0)
    .map(cat => ({ value: cat.slug || cat.categoryId, label: cat.name }));

  const makeOptions = makes.map(make => ({
    value: make.vehicleMakeId,
    label: make.name
  }));

  const modelOptions = models.map((model: any, index) => ({
    value: model.vehicleModelId || model.modelId || model.id || index,
    label: model.name
  }));

  return (
    <div className={styles.heroSearchWrapper}>
      <form className={styles.searchForm} onSubmit={handleSearch}>

        <h3 className={styles.mobileFormTitle}>قطعه مناسب خودروی خودت رو پیدا کن</h3>

        <div className={styles.formGroup}>
          <SearchableSelect 
            options={mainCategories}
            value={selectedCategory}
            onChange={(val) => setSelectedCategory(String(val))}
            placeholder="دسته بندی *"
          />
        </div>

        <div className={styles.divider}></div>

        <div className={styles.formGroup}>
          <SearchableSelect 
            options={makeOptions}
            value={selectedMake}
            onChange={(val) => setSelectedMake(String(val))}
            placeholder="ماشین *"
          />
        </div>

        <div className={styles.divider}></div>

        <div className={styles.formGroup}>
          <SearchableSelect 
            options={modelOptions}
            value={selectedModel}
            onChange={(val) => setSelectedModel(String(val))}
            placeholder="مدل تولید *"
            disabled={!selectedMake || models.length === 0}
          />
        </div>

        <button type="submit" className={styles.searchBtn}>
          <span>جست و جو</span>
        </button>

      </form>
    </div>
  );
}

