/**
 * کش کوچک in-memory برای GETهای پرتکرار.
 *
 * اهداف:
 * - درخواست‌های هم‌زمان با یک key روی یک Promise مشترک dedupe شوند.
 * - نتیجه موفق برای TTL مشخص نگه داشته شود.
 * - با سقف تعداد entry از رشد بدون کنترل RAM جلوگیری شود.
 * - invalidate شدن یک key/prefix اجازه ندهد Promise قدیمی دوباره cache کهنه بسازد.
 */

type CacheEntry<T> = {
  value: T;
  expiresAt: number;
};

const responseCache = new Map<string, CacheEntry<unknown>>();
const inFlightRequests = new Map<string, Promise<unknown>>();
const MAX_CACHE_ENTRIES = 100;
let cacheScope = 'anonymous';

/** هر پاسخ کش‌شده به هویت فعلی متصل می‌شود تا بین کاربران نشت نکند. */
export const setRequestCacheIdentity = (identity: string | null | undefined): void => {
  const nextScope = identity?.trim() || 'anonymous';
  if (nextScope === cacheScope) return;
  cacheScope = nextScope;
  responseCache.clear();
  inFlightRequests.clear();
};

const scopedKey = (key: string): string => `${cacheScope}:${key}`;

const pruneCache = (): void => {
  const now = Date.now();

  for (const [key, entry] of responseCache) {
    if (entry.expiresAt <= now) {
      responseCache.delete(key);
    }
  }

  while (responseCache.size > MAX_CACHE_ENTRIES) {
    const oldestKey = responseCache.keys().next().value as string | undefined;
    if (!oldestKey) break;
    responseCache.delete(oldestKey);
  }
};

export const getCachedRequest = async <T>(
  key: string,
  request: () => Promise<T>,
  ttlMs: number,
): Promise<T> => {
  const keyWithScope = scopedKey(key);
  pruneCache();

  const cached = responseCache.get(keyWithScope) as CacheEntry<T> | undefined;
  if (cached && cached.expiresAt > Date.now()) {
    // LRU سبک: entry خوانده‌شده به انتهای Map منتقل می‌شود.
    responseCache.delete(keyWithScope);
    responseCache.set(keyWithScope, cached);
    return cached.value;
  }

  const pending = inFlightRequests.get(keyWithScope) as Promise<T> | undefined;
  if (pending) {
    return pending;
  }

  let requestPromise: Promise<T>;

  requestPromise = request()
    .then((value) => {
      /*
       * اگر بین شروع و پایان درخواست mutation باعث invalidate شده باشد،
       * inFlight entry حذف شده و پاسخ قدیمی دیگر cache نمی‌شود.
       */
      if (inFlightRequests.get(keyWithScope) === requestPromise && ttlMs > 0) {
        responseCache.set(keyWithScope, {
          value,
          expiresAt: Date.now() + ttlMs,
        });
        pruneCache();
      }

      return value;
    })
    .finally(() => {
      if (inFlightRequests.get(keyWithScope) === requestPromise) {
        inFlightRequests.delete(keyWithScope);
      }
    });

  inFlightRequests.set(keyWithScope, requestPromise);
  return requestPromise;
};

/** فقط dedupe درخواست‌های هم‌زمان؛ بدون نگه‌داشتن response پس از پایان request. */
export const getDedupedRequest = <T>(
  key: string,
  request: () => Promise<T>,
): Promise<T> => getCachedRequest(key, request, 0);

export const invalidateRequestCache = (prefix?: string): void => {
  if (!prefix) {
    responseCache.clear();
    inFlightRequests.clear();
    return;
  }

  const prefixWithScope = scopedKey(prefix);
  for (const key of Array.from(responseCache.keys())) {
    if (key.startsWith(prefixWithScope)) {
      responseCache.delete(key);
    }
  }

  /*
   * Promise شبکه قابل cancel عمومی نیست، اما حذف از Map باعث می‌شود:
   * 1) درخواست جدید بعد از mutation به Promise قدیمی وصل نشود.
   * 2) Promise قدیمی بعد از resolve نتواند cache stale ایجاد کند.
   */
  for (const key of Array.from(inFlightRequests.keys())) {
    if (key.startsWith(prefixWithScope)) {
      inFlightRequests.delete(key);
    }
  }
};

// src/services/api/product/productApi.ts

import { OperationResult } from "@/models/common/OperationResult";
import axiosClient from "@/services/api/common/axiosClient";
import { ProductFilters } from "@/models/product/ProductFilters";
import { Product } from "@/models/product/Product";
import { ProductDetails } from "@/models/product/ProductDetails";
import { PagedResult } from "@/models/common/PagedResult";
import { createProductFilterRequestKey, ProductFilterParams } from "@/models/product/ProductFilters";
import { ProductBundleDto } from "@/models/ProductBundle/ProductBundle";
import { getCachedRequest } from "@/services/api/common/requestCache";

export const ProductApi = {
  // 🟢 اصلاح شد: اتصال به اکشن پیشرفته filtered در بک‌اند برای پشتیبانی کامل از فیلترها و ماشین‌ها
  getAll: (filters?: ProductFilters & { vehicleIds?: any; page?: number; pageSize?: number }) => {
    const formattedParams: any = { ...filters };

    if (filters?.vehicleIds && Array.isArray(filters.vehicleIds) && filters.vehicleIds.length > 0) {
      formattedParams.vehicleIds = filters.vehicleIds
        .map((v: any) => `${v.makeId}-${v.modelId}`)
        .join(',');
    } else {
      delete formattedParams.vehicleIds;
    }

    const key = `product:all:${createProductFilterRequestKey(filters ?? {})}`;
    return getCachedRequest(
      key,
      () => axiosClient.get<OperationResult<PagedResult<Product>>>('/Product/filtered', { params: formattedParams }),
      15_000,
    );
  },

  getDetails: (id: number | string) =>
    getCachedRequest(
      `product:details:${id}`,
      () => axiosClient.get<OperationResult<ProductDetails>>(`/Product/${id}/details`),
      30_000,
    ),

  getById: (id: number | string) =>
    getCachedRequest(
      `product:by-id:${id}`,
      () => axiosClient.get<OperationResult<Product>>(`/Product/${id}`),
      30_000,
    ),

  search: (keyword: string) => {
    const normalizedKeyword = keyword.trim().toLocaleLowerCase('fa-IR');
    return getCachedRequest(
      `product:search:${normalizedKeyword}`,
      () => axiosClient.get<OperationResult<Product[]>>('/Product/search', { params: { keyword: keyword.trim() } }),
      30_000,
    );
  },

  getBySlug: (name: string) => {
    const normalizedName = name.trim();
    const isNumericId = /^\d+$/.test(normalizedName);
    const endpoint = isNumericId
      ? `/Product/${normalizedName}/details`
      : `/Product/${encodeURIComponent(normalizedName)}`;

    return getCachedRequest(
      `product:slug:${normalizedName.toLocaleLowerCase('fa-IR')}`,
      () => axiosClient.get<OperationResult<ProductDetails>>(endpoint),
      30_000,
    );
  },

  getBestSellers: (pageNumber: number = 1, pageSize: number = 5, includeAll: boolean = true) =>
    getCachedRequest(
      `product:best-sellers:${pageNumber}:${pageSize}:${includeAll}`,
      () => axiosClient.get<OperationResult<PagedResult<Product>>>('/Product/best-sellers', {
        params: { pageNumber, pageSize, includeAll }
      }),
      60_000,
    ),

  getFeaturedPaged: (pageNumber: number = 1, pageSize: number = 5) =>
    getCachedRequest(
      `product:featured:${pageNumber}:${pageSize}`,
      () => axiosClient.get<OperationResult<PagedResult<Product>>>('/Product/featured-paged', {
        params: { pageNumber, pageSize }
      }),
      60_000,
    ),

  getDiscountedPaged: (pageNumber: number = 1, pageSize: number = 5) =>
    getCachedRequest(
      `product:discounted:${pageNumber}:${pageSize}`,
      () => axiosClient.get<OperationResult<PagedResult<Product>>>('/Product/discounted-paged', {
        params: { pageNumber, pageSize }
      }),
      60_000,
    ),

  getFiltered: (params: ProductFilterParams) =>
    getCachedRequest(
      `product:filtered:${createProductFilterRequestKey(params)}`,
      () => axiosClient.get('/Product/filtered', { params }),
      30_000,
    ),

  getEffectivePrice: (productId: number | string) =>
    getCachedRequest(
      `product:effective-price:${productId}`,
      () => axiosClient.get<OperationResult<number>>(`/ProductPricing/${productId}/effective-price`),
      30_000,
    ),

  // این endpoint همه bundleها را برمی‌گرداند؛ روی هر PDP نباید مجدداً دانلود شود.
  getAllBundles: () =>
    getCachedRequest(
      'product-bundles:all',
      () => axiosClient.get<OperationResult<ProductBundleDto[]>>('/product-bundles/get-all'),
      5 * 60_000,
    ),

  getBundlesByProduct: (productId: number | string) =>
    getCachedRequest(
      `product-bundles:product:${productId}`,
      () => axiosClient.get<OperationResult<ProductBundleDto[]>>(`/product-bundles/get-by-product/${productId}`),
      5 * 60_000,
    ),

  getBundleById: (id: number | string) =>
    getCachedRequest(
      `product-bundle:${id}`,
      () => axiosClient.get<OperationResult<ProductBundleDto>>(`/product-bundles/get-by-id/${id}`),
      60_000,
    ),
};

// features/address/redux/AddressThunks.ts
import { createAsyncThunk } from '@reduxjs/toolkit';
import type { AddressResponseDto } from '@/models/address/AddressResponseDto';
import type { CreateAddressDto } from '@/models/address/CreateAddressDto';
import type { UpdateAddressDto } from '@/models/address/UpdateAddressDto';
import { AddressApi } from '@/features/address/api/AddressApi';

const getErrorMessage = (error: any): string => {
  if (error.response?.data?.message) return error.response.data.message;
  if (error.response?.data?.errors) {
    const errors = error.response.data.errors;
    if (Array.isArray(errors)) return errors.join(', ');
    if (typeof errors === 'object') return Object.values(errors).flat().join(', ');
  }
  if (error.message) return error.message;
  return 'خطای ناشناخته رخ داد';
};

// ============================
// دریافت همه آدرس‌ها (سازگار با PagedResult)
// ============================
const ADDRESS_CACHE_TTL_MS = 60_000;

type AddressFetchArgs = { force?: boolean } | undefined;

type AddressRootState = {
  address: {
    fetchStatus?: 'idle' | 'loading' | 'succeeded' | 'failed';
    lastFetchedAt?: number | null;
  };
};

export const fetchAddresses = createAsyncThunk<
  { addresses: AddressResponseDto[]; fetchedAt: number },
  AddressFetchArgs,
  { state: AddressRootState; rejectValue: string }
>(
  'address/fetchAll',
  async (_, { rejectWithValue }) => {
    try {
      const response = await AddressApi.getAll();

      if (response.data?.isSuccess) {
        const resData: any = response.data.data;
        let addresses: AddressResponseDto[] = [];

        if (Array.isArray(resData)) addresses = resData;
        else if (resData?.items && Array.isArray(resData.items)) addresses = resData.items;
        else if (resData?.Items && Array.isArray(resData.Items)) addresses = resData.Items;

        return { addresses, fetchedAt: Date.now() };
      }

      return rejectWithValue(response.data?.message || 'خطا در دریافت آدرس‌ها');
    } catch (error: any) {
      return rejectWithValue(getErrorMessage(error));
    }
  },
  {
    condition: (args, { getState }) => {
      const state = getState().address;
      if (state.fetchStatus === 'loading') return false;
      if (args?.force) return true;
      if (!state.lastFetchedAt) return true;
      return Date.now() - state.lastFetchedAt >= ADDRESS_CACHE_TTL_MS;
    },
  },
);

// ============================
// ایجاد آدرس جدید
// ============================
export const createAddress = createAsyncThunk<AddressResponseDto, CreateAddressDto>(
  'address/create',
  async (data, { rejectWithValue }) => {
    try {
      const response = await AddressApi.create(data);
      if (response.data?.isSuccess) {
        const resData: any = response.data.data;
        if (Array.isArray(resData)) return resData[0];
        return resData;
      }
