import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { fetchMyOrders, fetchOrderDetail, cancelOrder } from './orderThunks';
import { placeOrderFromCart } from '@/store/feature/cart/cartThunks';
import { OrderDto } from '@/models/order/OrderDto';

interface OrderState {
  orders: OrderDto[];
  selectedOrder: OrderDto | null;
  activeTab: 'all' | 'current' | 'completed' | 'cancelled';
  pagination: {
    currentPage: number;
    totalPages: number;
    totalCount: number;
    pageSize: number;
  };
  loading: boolean;
  detailLoading: boolean;
  actionLoading: boolean;
  error: string | null;
  lastListFetchKey: string | null;
  lastListFetchedAt: number | null;
}

const initialState: OrderState = {
  orders: [],
  selectedOrder: null,
  activeTab: 'all',
  pagination: {
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
    pageSize: 10,
  },
  loading: false,
  detailLoading: false,
  actionLoading: false,
  error: null,
  lastListFetchKey: null,
  lastListFetchedAt: null,
};

const orderSlice = createSlice({
  name: 'orders',
  initialState,
  reducers: {
    setActiveTab: (state, action: PayloadAction<'all' | 'current' | 'completed' | 'cancelled'>) => {
      state.activeTab = action.payload;
    },
    clearOrderError: (state) => { 
      state.error = null; 
    },
    clearSelectedOrder: (state) => { 
      state.selectedOrder = null; 
    },
  },
  extraReducers: (builder) => {
    // ─── Fetch My Orders ───
    builder
      .addCase(fetchMyOrders.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMyOrders.fulfilled, (state, action) => {
        state.loading = false;
        const result = action.payload.result;
        state.orders = result.orders;
        state.lastListFetchKey = action.payload.fetchKey;
        state.lastListFetchedAt = action.payload.fetchedAt;
        state.pagination = {
          currentPage: result.currentPage,
          totalPages: result.totalPages,
          totalCount: result.totalCount,
          pageSize: result.pageSize,
        };
      })
      .addCase(fetchMyOrders.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });

    // ─── Fetch Order Detail ───
    builder
      .addCase(fetchOrderDetail.pending, (state) => {
        state.detailLoading = true;
        state.error = null;
      })
      .addCase(fetchOrderDetail.fulfilled, (state, action) => {
        state.detailLoading = false;
        state.selectedOrder = action.payload;
      })
      .addCase(fetchOrderDetail.rejected, (state, action) => {
        state.detailLoading = false;
        state.error = action.payload as string;
      });

    // ─── Cancel Order ───
    builder
      .addCase(cancelOrder.pending, (state) => {
        state.actionLoading = true;
        state.error = null;
      })
      .addCase(cancelOrder.fulfilled, (state, action) => {
        state.actionLoading = false;
        const index = state.orders.findIndex(o => o.orderId === action.payload);
        if (index !== -1) {
          state.orders[index].orderStatus = 'Cancelled';
          state.orders[index].orderStatusId = 8;
        }
        if (state.selectedOrder?.orderId === action.payload) {
          state.selectedOrder.orderStatus = 'Cancelled';
          state.selectedOrder.orderStatusId = 8;
        }
        state.lastListFetchedAt = null;
      })
      .addCase(cancelOrder.rejected, (state, action) => {
        state.actionLoading = false;
        state.error = action.payload as string;
      });

    // ─── Place Order From Cart ───
    builder
      .addCase(placeOrderFromCart.pending, (state) => {
        state.actionLoading = true;
        state.error = null;
      })
      .addCase(placeOrderFromCart.fulfilled, (state, action) => {
        state.actionLoading = false;
        state.activeTab = 'current';
        // چک کن payload وجود داره و ساختار OrderDto رو داره
        if (action.payload && 'orderId' in action.payload) {
          state.orders.unshift(action.payload as any);
        }
      })
      .addCase(placeOrderFromCart.rejected, (state, action) => {
        state.actionLoading = false;
        state.error = action.payload as string;
      });
  },
});

export const { setActiveTab, clearOrderError, clearSelectedOrder } = orderSlice.actions;
export default orderSlice.reducer;

import { OrderApi } from '@/features/orders/api/orderApi';
import { createAsyncThunk } from '@reduxjs/toolkit';

const ORDER_LIST_CACHE_TTL_MS = 30_000;

type FetchOrdersArgs = { page?: number; pageSize?: number; force?: boolean } | undefined;
type OrdersRootState = {
  orders: {
    loading: boolean;
    detailLoading: boolean;
    lastListFetchKey: string | null;
    lastListFetchedAt: number | null;
    selectedOrder: { orderId?: number } | null;
  };
};

export const fetchMyOrders = createAsyncThunk<
  any,
  FetchOrdersArgs,
  { state: OrdersRootState; rejectValue: string }
>(
  'orders/fetchMyOrders',
  async (args = {}, { rejectWithValue }) => {
    const { page = 1, pageSize = 10 } = args || {};
    try {
      const response = await OrderApi.getMyOrders(page, pageSize);
      if (response.data.isSuccess) {
        return {
          result: response.data.data,
          fetchKey: `${page}:${pageSize}`,
          fetchedAt: Date.now(),
        };
      }
      return rejectWithValue(response.data.message || 'خطا در دریافت سفارش‌ها');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطا در دریافت سفارش‌ها');
    }
  },
  {
    condition: (args, { getState }) => {
      const state = getState().orders;
      if (state.loading) return false;
      if (args?.force) return true;
      const page = args?.page ?? 1;
      const pageSize = args?.pageSize ?? 10;
      const key = `${page}:${pageSize}`;
      return !state.lastListFetchedAt || state.lastListFetchKey !== key || Date.now() - state.lastListFetchedAt >= ORDER_LIST_CACHE_TTL_MS;
    },
  },
);

export const fetchOrderDetail = createAsyncThunk<
  any,
  number,
  { state: OrdersRootState; rejectValue: string }
>(
  'orders/fetchOrderDetail',
  async (id, { rejectWithValue }) => {
    try {
      const response = await OrderApi.getOrderDetail(id);
      if (response.data.isSuccess) return response.data.data;
      return rejectWithValue(response.data.message || 'خطا در دریافت جزئیات سفارش');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطا در دریافت جزئیات سفارش');
    }
  },
  {
    condition: (id, { getState }) => {
      const state = getState().orders;
      if (state.detailLoading) return false;
      return state.selectedOrder?.orderId !== id;
    },
  },
);

export const cancelOrder = createAsyncThunk(
  'orders/cancelOrder',
  async ({ id, reason }: { id: number; reason: string }, { rejectWithValue }) => {
    try {
      const response = await OrderApi.cancelOrder(id, reason);
      if (response.data.isSuccess) return id;
      return rejectWithValue(response.data.message || 'خطا در لغو سفارش');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطا در لغو سفارش');
    }
  }
);

import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { 
  fetchMyProfile, 
  updateProfile, 
  changePassword, 
  uploadAvatar, 
  deleteAvatar 
} from './profileThunks';

interface ProfileState {
  data: any | null;
  loading: boolean;
  updating: boolean;
  changingPassword: boolean;
  uploadingAvatar: boolean;
  error: string | null;
  successMessage: string | null;
  lastFetchedAt: number | null;
}

const initialState: ProfileState = {
  data: null,
  loading: false,
  updating: false,
  changingPassword: false,
  uploadingAvatar: false,
  error: null,
  successMessage: null,
  lastFetchedAt: null,
};

const profileSlice = createSlice({
  name: 'profile',
  initialState,
  reducers: {
    clearProfileMessages: (state) => {
      state.error = null;
      state.successMessage = null;
      state.lastFetchedAt = null;
    },
    clearProfileState: (state) => {
      state.data = null;
      state.error = null;
      state.successMessage = null;
    },
  },
  extraReducers: (builder) => {
    // ─── Fetch My Profile ───
    builder
      .addCase(fetchMyProfile.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMyProfile.fulfilled, (state, action) => {
        state.loading = false;
        state.data = action.payload.data;
        state.lastFetchedAt = action.payload.fetchedAt;
      })
      .addCase(fetchMyProfile.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });

    // ─── Update Profile ───
    builder
      .addCase(updateProfile.pending, (state) => {
        state.updating = true;
        state.error = null;
        state.successMessage = null;
      })
      .addCase(updateProfile.fulfilled, (state, action) => {
        state.updating = false;
        state.data = action.payload;
        state.lastFetchedAt = Date.now();
        state.successMessage = 'پروفایل با موفقیت بروزرسانی شد.';
      })
      .addCase(updateProfile.rejected, (state, action) => {
        state.updating = false;
        state.error = action.payload as string;
      });

    // ─── Change Password ───
    builder
      .addCase(changePassword.pending, (state) => {
        state.changingPassword = true;
        state.error = null;
        state.successMessage = null;
      })
      .addCase(changePassword.fulfilled, (state, action) => {
        state.changingPassword = false;
        state.successMessage = action.payload;
      })
      .addCase(changePassword.rejected, (state, action) => {
        state.changingPassword = false;
        state.error = action.payload as string;
      });

    // ─── Upload Avatar ───
    builder
      .addCase(uploadAvatar.pending, (state) => {
        state.uploadingAvatar = true;
        state.error = null;
      })
      .addCase(uploadAvatar.fulfilled, (state, action) => {
        state.uploadingAvatar = false;
        if (state.data?.userProfile) {
          state.data.userProfile.avatarUrl = action.payload;
        }
        state.successMessage = 'آواتار با موفقیت آپلود شد.';
      })
      .addCase(uploadAvatar.rejected, (state, action) => {
        state.uploadingAvatar = false;
        state.error = action.payload as string;
      });

    // ─── Delete Avatar ───
    builder
      .addCase(deleteAvatar.pending, (state) => {
        state.uploadingAvatar = true;
        state.error = null;
      })
      .addCase(deleteAvatar.fulfilled, (state) => {
        state.uploadingAvatar = false;
        if (state.data?.userProfile) {
          state.data.userProfile.avatarUrl = '';
        }
        state.successMessage = 'آواتار با موفقیت حذف شد.';
      })
      .addCase(deleteAvatar.rejected, (state, action) => {
        state.uploadingAvatar = false;
        state.error = action.payload as string;
      });
  },
});

export const { clearProfileMessages, clearProfileState } = profileSlice.actions;
export default profileSlice.reducer;

import { createAsyncThunk } from '@reduxjs/toolkit';
import { profileApi, UpdateProfileRequest, ChangePasswordRequest } from '@/features/profile/api/profileApi';

const PROFILE_CACHE_TTL_MS = 60_000;

type ProfileFetchArgs = { force?: boolean } | undefined;
type ProfileRootState = {
  profile: {
    data: unknown | null;
    loading: boolean;
    lastFetchedAt: number | null;
  };
};

export const fetchMyProfile = createAsyncThunk<
  { data: any; fetchedAt: number },
  ProfileFetchArgs,
  { state: ProfileRootState; rejectValue: string }
>(
  'profile/fetchMyProfile',
  async (_, { rejectWithValue }) => {
    try {
      const response = await profileApi.getMyProfile();
      if (response.data.isSuccess) {
        return { data: response.data.data, fetchedAt: Date.now() };
      }
      return rejectWithValue(response.data.message || 'خطا در دریافت پروفایل');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطای شبکه');
    }
  },
  {
    condition: (args, { getState }) => {
      const state = getState().profile;
      if (state.loading) return false;
      if (args?.force) return true;
      if (!state.data || !state.lastFetchedAt) return true;
      return Date.now() - state.lastFetchedAt >= PROFILE_CACHE_TTL_MS;
    },
  },
);

export const updateProfile = createAsyncThunk(
  'profile/updateProfile',
  async (data: UpdateProfileRequest, { rejectWithValue }) => {
    try {
      const response = await profileApi.updateProfile(data);
      if (response.data.isSuccess) return response.data.data;
      return rejectWithValue(response.data.message || 'خطا در بروزرسانی پروفایل');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطای شبکه');
    }
  }
);

export const changePassword = createAsyncThunk(
  'profile/changePassword',
  async (data: ChangePasswordRequest, { rejectWithValue }) => {
    try {
      const response = await profileApi.changePassword(data);
      if (response.data.isSuccess) return response.data.message;
      return rejectWithValue(response.data.message || 'خطا در تغییر رمز عبور');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطای شبکه');
    }
  }
);

export const uploadAvatar = createAsyncThunk(
  'profile/uploadAvatar',
  async (file: File, { rejectWithValue }) => {
    try {
      const response = await profileApi.uploadAvatar(file);
      if (response.data.isSuccess) return response.data.data.avatarUrl;
      return rejectWithValue(response.data.message || 'خطا در آپلود آواتار');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطای شبکه');
    }
  }
);

export const deleteAvatar = createAsyncThunk(
  'profile/deleteAvatar',
  async (_, { rejectWithValue }) => {
    try {
      const response = await profileApi.deleteAvatar();
      if (response.data.isSuccess) return true;
      return rejectWithValue(response.data.message || 'خطا در حذف آواتار');
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'خطای شبکه');
    }
  }
);

