'use client';

import {
  type CSSProperties,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from 'react';

interface LazyMountProps {
  children: ReactNode;
  fallback?: ReactNode;
  className?: string;
  rootMargin?: string;
  minHeight?: number | string;
}

/**
 * فرزندان را فقط زمانی Mount می‌کند که سکشن
 * به محدوده دید کاربر نزدیک شود.
 *
 * در نتیجه useEffectها و درخواست‌های API داخل سکشن
 * قبل از نیاز کاربر اجرا نمی‌شوند.
 */
export default function LazyMount({
  children,
  fallback = null,
  className,
  rootMargin = '500px 0px',
  minHeight = 0,
}: LazyMountProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [shouldMount, setShouldMount] = useState(false);

  useEffect(() => {
    if (shouldMount) {
      return;
    }

    const element = containerRef.current;

    if (!element) {
      return;
    }

    /*
     * در مرورگرهای قدیمی که IntersectionObserver ندارند،
     * محتوا بلافاصله نمایش داده می‌شود تا صفحه خراب نشود.
     */
    if (!('IntersectionObserver' in window)) {
      setShouldMount(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) {
          return;
        }

        setShouldMount(true);

        /*
         * بعد از اولین Mount دیگر نیازی به Observer نداریم.
         * محتوا پس از خارج‌شدن از Viewport نیز Mount باقی می‌ماند.
         */
        observer.disconnect();
      },
      {
        root: null,
        rootMargin,
        threshold: 0,
      },
    );

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [rootMargin, shouldMount]);

  const placeholderStyle: CSSProperties | undefined =
    shouldMount
      ? undefined
      : {
          minHeight,
        };

  return (
    <div
      ref={containerRef}
      className={className}
      style={placeholderStyle}
    >
      {shouldMount ? children : fallback}
    </div>
  );
}

/**
 * قوانین نمایش قیمت در فرانت:
 * - مبلغ‌ها با واحد واقعی تومان نمایش داده می‌شوند و گرد کردن درشت ندارند.
 * - مالیات در جمع‌های سمت فرانت لحاظ نمی‌شود.
 */
export const PRICE_ROUNDING_STEP = 1;

export const roundPrice = (value: number | null | undefined): number => {
  const numericValue = Number(value ?? 0);

  if (!Number.isFinite(numericValue)) {
    return 0;
  }

  return Math.max(
    0,
    Math.round(numericValue / PRICE_ROUNDING_STEP) * PRICE_ROUNDING_STEP,
  );
};

export const formatPrice = (value: number | null | undefined): string =>
  new Intl.NumberFormat('fa-IR').format(roundPrice(value));


export const calculateRoundedCartSubtotal = (cart: any): number => {
  if (Array.isArray(cart?.items) && cart.items.length > 0) {
    return cart.items.reduce((sum: number, item: any) => {
      const unitPrice = roundPrice(item?.unitPrice ?? item?.price ?? 0);
      const quantity = Math.max(0, Number(item?.quantity ?? 0));
      return sum + unitPrice * quantity;
    }, 0);
  }

  return roundPrice(cart?.subTotal ?? cart?.totalAmount ?? 0);
};

export const calculateRoundedCartDiscount = (cart: any): number =>
  roundPrice(cart?.totalDiscount ?? 0);

export const calculateTaxFreeCartTotal = (cart: any): number => {
  const subTotal = calculateRoundedCartSubtotal(cart);
  const discount = calculateRoundedCartDiscount(cart);

  return Math.max(0, subTotal - discount);
};

export const calculateTaxFreeOrderTotal = (order: any): number => {
  const hasSubtotal = Number.isFinite(Number(order?.subtotal));

  if (hasSubtotal) {
    const subtotal = roundPrice(order?.subtotal ?? 0);
    const discount = roundPrice(order?.discountTotal ?? 0);
    const shipping = Array.isArray(order?.shipments)
      ? order.shipments.reduce(
          (sum: number, shipment: any) => sum + roundPrice(shipment?.shippingCost ?? 0),
          0,
        )
      : 0;

    return Math.max(0, subtotal - discount + shipping);
  }

  // fallback برای پاسخ‌های قدیمی API که فقط grandTotal/taxTotal دارند.
  return roundPrice((order?.grandTotal ?? 0) - (order?.taxTotal ?? 0));
};

'use client';

import React, { useEffect, useRef, useState, ReactNode } from 'react';

interface FadeInScrollProps {
  children: ReactNode;
  className?: string;
}

export const FadeInScroll: React.FC<FadeInScrollProps> = ({ children, className = '' }) => {
  const ref = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => {
      if (ref.current) {
        observer.unobserve(ref.current);
      }
    };
  }, []);

  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: isVisible ? 1 : 0,
        transform: isVisible ? 'translateY(0)' : 'translateY(20px)',
        transition: 'opacity 0.6s ease-out, transform 0.6s ease-out',
        touchAction: 'pan-y', // 👈 این خط رو اضافه کن
      }}
    >
      {children}
    </div>
  );
};

'use client';

import dynamic from 'next/dynamic';
import Link from 'next/link';
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  HeadphonesIcon,
  ShieldCheck,
  Trophy,
  Truck,
} from 'lucide-react';

import BuyBox from '@/components/product/BuyBox/BuyBox';
import ProductGallery from '@/components/product/ProductGallery/ProductGallery';
import ProductInfo from '@/components/product/ProductInfo/ProductInfo';
import ProductSpecifications from '@/components/product/ProductSpecifications/ProductSpecifications';
import ProductTabs from '@/components/product/ProductTabs/ProductTabs';
import LazyMount from '@/components/utils/lazy/LazyMount';
import type { FeatureValueItem } from '@/models/Featurevalues/FeatureValueItem';
import type { ProductDetails } from '@/models/product/ProductDetails';
import { useAppDispatch, useAppSelector } from '@/store/hooks';
import {
  clearProductDetail,
  initializeProductDetail,
} from '@/store/feature/product/productDetailSlice';
import { fetchEffectivePrice } from '@/store/feature/product/productThunks';
import {
  clearProductDetails,
  setProductDetails,
} from '@/store/feature/product/productSlice';
import { selectProductDetails } from '@/store/feature/product/productSelectors';

import styles from './ProductDetail.module.scss';

const ProductReviews = dynamic(
  () =>
    import(
      '@/components/product/ProductReviews/ProductReviews'
    ),
  {
    ssr: false,
    loading: () => (
      <div className={styles.loadingTab}>
        در حال بارگذاری نظرات...
      </div>
    ),
  },
);

const ProductQuestions = dynamic(
  () =>
    import(
      '@/components/product/ProductQuestions/ProductQuestions'
    ),
  {
    ssr: false,
    loading: () => (
      <div className={styles.loadingTab}>
        در حال بارگذاری پرسش‌ها...
      </div>
    ),
  },
);

const RelatedProducts = dynamic(
  () =>
    import(
      '@/components/product/RelatedProducts/RelatedProducts'
    ),
  {
    ssr: false,
    loading: () => (
      <div className={styles.loadingTab}>
        در حال بارگذاری پیشنهادها...
      </div>
    ),
  },
);

interface ProductDetailPageProps {
  initialProduct: ProductDetails;
}

interface ProductTab {
  id: string;
  label: string;
  content: ReactNode;
}

interface NormalizedSpecification {
  featureValueId?: number;
  featureId?: number;
  featureName: string;
  valueString?: string | null;
  valueNumeric?: number | null;
  optionName?: string | null;
  unit?: string | null;
  source?: string;
}

function parseFeatureValues(
  featureValues: unknown,
): FeatureValueItem[] {
  if (Array.isArray(featureValues)) {
    return featureValues as FeatureValueItem[];
  }

  if (typeof featureValues !== 'string') {
    return [];
  }

  try {
    const parsed = JSON.parse(featureValues);

    return Array.isArray(parsed)
      ? (parsed as FeatureValueItem[])
      : [];
  } catch {
    return [];
  }
}

function hasRealSpecifications(
  product: ProductDetails,
): boolean {
  return parseFeatureValues(
    product.featureValues,
  ).some((feature) => {
    const value =
      feature.optionName ??
      feature.valueString ??
      feature.valueNumeric;

    return (
      value !== undefined &&
      value !== null &&
      value !== '' &&
      value !== '-'
    );
  });
}

function getDefaultTab(
  product: ProductDetails,
): string {
  if (
    product.fullDescription ||
    product.shortDescription
  ) {
    return 'description';
  }

  if (hasRealSpecifications(product)) {
    return 'specifications';
  }

  return 'reviews';
}

export default function ProductDetailPageClient({
  initialProduct,
}: ProductDetailPageProps) {
  const dispatch = useAppDispatch();
  const storeProduct = useAppSelector(
    selectProductDetails,
  );
  const tabsSectionRef =
    useRef<HTMLDivElement>(null);

  const product =
    storeProduct?.productId ===
    initialProduct.productId
      ? storeProduct
      : initialProduct;

  const [activeTab, setActiveTab] =
    useState<string>(() =>
      getDefaultTab(initialProduct),
    );

  useEffect(() => {
    const productId =
      initialProduct.productId;

    dispatch(
      initializeProductDetail(productId),
    );
    dispatch(
      setProductDetails(initialProduct),
    );

    /*
     * قیمت برای BuyBox بالای صفحه لازم است؛ بنابراین تنها
     * درخواست تکمیلی‌ای است که بلافاصله اجرا می‌شود.
     */
    void dispatch(
      fetchEffectivePrice({ productId }),
    );

    setActiveTab(
      getDefaultTab(initialProduct),
    );

    return () => {
      dispatch(clearProductDetails());
      dispatch(clearProductDetail());
    };
  }, [dispatch, initialProduct]);

  const handleNavigateToTab = (
    tabId: string,
  ) => {
    setActiveTab(tabId);

    window.setTimeout(() => {
      tabsSectionRef.current?.scrollIntoView({
        behavior: 'smooth',
        block: 'start',
      });
    }, 100);
  };

  const specifications = useMemo<
    NormalizedSpecification[]
  >(() => {
    return parseFeatureValues(
      product.featureValues,
    ).map((feature) => ({
      featureValueId:
        feature.featureValueId,
      featureId: feature.featureId,
      featureName:
        feature.featureName || 'ویژگی',
      valueString: feature.valueString,
      valueNumeric: feature.valueNumeric,
      optionName: feature.optionName,
      unit: feature.unit,
      source: feature.source || 'Product',
    }));
  }, [product.featureValues]);

  const tabs = useMemo<ProductTab[]>(() => {
    const result: ProductTab[] = [];

    if (
      product.fullDescription ||
      product.shortDescription
    ) {
      result.push({
        id: 'description',
        label: 'توضیحات محصول',
        content: (
          <div
            className={styles.descriptionTab}
          >
            {product.fullDescription ? (
              <div
                dangerouslySetInnerHTML={{
                  __html:
                    product.fullDescription,
                }}
              />
            ) : (
              <p>
                {product.shortDescription}
              </p>
            )}
          </div>
        ),
      });
    }

    result.push({
      id: 'specifications',
      label: 'مشخصات فنی',
      content: (
        <ProductSpecifications
          specifications={specifications}
        />
      ),
    });

    result.push(
      {
        id: 'reviews',
        label: 'نظرات کاربران',
        content: (
          <ProductReviews
            productId={product.productId}
          />
        ),
      },
      {
        id: 'questions',
        label: 'پرسش و پاسخ',
        content: (
          <ProductQuestions
            productId={product.productId}
          />
        ),
      },
    );

    return result;
  }, [product, specifications]);

  return (
    <div className={styles.pageContainer}>
      <div className={styles.breadcrumb}>
        <Link
          href="/products"
          className={styles.breadcrumbLink}
        >
          محصولات
        </Link>

        {product.categoryName &&
          product.categoryName !== 'نامشخص' && (
            <>
              <span
                className={styles.separator}
              >
                /
              </span>

              <Link
                href={`/products/${product.categoryId}`}
                className={
                  styles.breadcrumbLink
                }
              >
                {product.categoryName}
              </Link>
            </>
          )}

        <span className={styles.separator}>
          /
        </span>
        <span className={styles.current}>
          {product.productName}
        </span>
      </div>

      <section className={styles.topSection}>
        <div className={styles.galleryColumn}>
          <ProductGallery />
        </div>

        <div className={styles.infoColumn}>
          <ProductInfo
            onNavigateToTab={
              handleNavigateToTab
            }
          />
        </div>

        <div className={styles.buyBoxColumn}>
          <BuyBox />
        </div>
      </section>

      <section
        className={styles.featuresBanner}
      >
        <div className={styles.featureBox}>
          <Trophy
            size={32}
            strokeWidth={1}
          />
          <div className={styles.featureText}>
            <h4>تضمین کیفیت</h4>
            <p>
              ساخته شده با بهترین متریال
            </p>
          </div>
        </div>

        <div className={styles.featureBox}>
          <ShieldCheck
            size={32}
            strokeWidth={1}
          />
          <div className={styles.featureText}>
            <h4>گارانتی</h4>
            <p>شش ماه خدمات پس از فروش</p>
          </div>
        </div>

        <div className={styles.featureBox}>
          <Truck
            size={32}
            strokeWidth={1}
          />
          <div className={styles.featureText}>
            <h4>ارسال سریع</h4>
            <p>
              ارسال سریع محصول به سراسر کشور
            </p>
          </div>
        </div>

        <div className={styles.featureBox}>
          <HeadphonesIcon
            size={32}
            strokeWidth={1}
          />
          <div className={styles.featureText}>
            <h4>پشتیبانی</h4>
            <p>پاسخگویی ۷ روز هفته</p>
          </div>
        </div>
      </section>

      <section
        className={styles.bottomSection}
        ref={tabsSectionRef}
      >
        <div className={styles.tabsWrapper}>
          <ProductTabs
            tabs={tabs}
            activeTab={activeTab}
            onTabChange={setActiveTab}
            defaultTab={getDefaultTab(product)}
          />
        </div>
      </section>

      <section
        className={styles.relatedSection}
      >
        <LazyMount
          rootMargin="600px 0px"
          minHeight={380}
          fallback={
            <div className={styles.loadingTab}>
              پیشنهادهای مرتبط در ادامه
              بارگذاری می‌شوند.
            </div>
          }
        >
          <RelatedProducts
            productId={product.productId}
          />
        </LazyMount>
      </section>
    </div>
  );
}
